_thumb_reconciled_this_run = False


def _thumb_session_note_start(extra_count):
    global _thumb_session_active, _thumb_session_generated, _thumb_session_failed, _thumb_session_total_at_start
    with _thumb_session_lock:
        if not _thumb_session_active:
            _thumb_session_active = True
            _thumb_session_generated = 0
            _thumb_session_failed = []
            _thumb_session_total_at_start = extra_count
        else:
            _thumb_session_total_at_start = max(_thumb_session_total_at_start, extra_count)
    _prevent_system_sleep(True)


def _thumb_session_note_result(name, path, ok, reason=None):
    global _thumb_session_generated
    with _thumb_session_lock:
        _thumb_session_generated += 1
        if not ok:
            _thumb_session_failed.append({'name': name, 'path': path, 'reason': reason or 'error'})


def _thumb_session_maybe_finish():
    global _thumb_session_active, _thumb_pending_summary
    finished = False
    with _thumb_session_lock:
        if _thumb_session_active and thumb_generation_queue.empty():
            _thumb_pending_summary = {
                'total': _thumb_session_total_at_start,
                'generated': _thumb_session_generated,
                'failed': list(_thumb_session_failed),
            }
            _thumb_session_active = False
            finished = True
    if finished:
        _prevent_system_sleep(False)


def get_thumb_timeout(file_path):
    try:
        size_mb = os.path.getsize(file_path) / (1024 * 1024)
    except OSError:
        return THUMB_GENERATION_TIMEOUT
    timeout = THUMB_GENERATION_TIMEOUT + size_mb * THUMB_GENERATION_TIMEOUT_PER_MB


    if file_path.lower().endswith('.3mf'):
        timeout *= 1.6
    return min(timeout, THUMB_GENERATION_TIMEOUT_MAX)


def _wv_dialog(wv, kind):
    """Constante de boîte de dialogue pywebview : FileDialog.SAVE/OPEN/FOLDER (SAVE_DIALOG… sont obsolètes)."""
    fd = getattr(wv, 'FileDialog', None)
    return getattr(fd, kind, None) or getattr(wv, kind + '_DIALOG')


def _wv_save_dialog(wv):
    return _wv_dialog(wv, 'SAVE')


_TRAY_LABELS = {
    'fr': ("Ouvrir Stellio", "Quitter Stellio", "Stellio est en cours d'exécution"),
    'en': ("Open Stellio", "Quit Stellio", "Stellio is running"),
    'de': ("Stellio öffnen", "Stellio beenden", "Stellio läuft"),
    'es': ("Abrir Stellio", "Salir de Stellio", "Stellio se está ejecutando"),
    'pt': ("Abrir o Stellio", "Sair do Stellio", "O Stellio está em execução"),
    'it': ("Apri Stellio", "Esci da Stellio", "Stellio è in esecuzione"),
    'zh': ("打开 Stellio", "退出 Stellio", "Stellio 正在运行"),
    'ja': ("Stellio を開く", "Stellio を終了", "Stellio は実行中です"),
}
_TRAY_STATE = {'started': False}


def _start_tray_icon(on_open, on_quit):
    """Icône Stellio dans la zone de notification de Windows (à côté de l'horloge) : montre que Stellio tourne,
    clic = ouvrir, clic droit = Ouvrir / Quitter. Implémentée avec l'API Windows (aucune dépendance à installer)."""
    if os.name != 'nt' or _TRAY_STATE['started']:
        return
    _TRAY_STATE['started'] = True

    def _run():
        try:
            import ctypes
            from ctypes import wintypes
            user32, shell32, kernel32 = ctypes.windll.user32, ctypes.windll.shell32, ctypes.windll.kernel32
            LRESULT = ctypes.c_ssize_t
            WM_USER, WM_DESTROY, WM_NULL = 0x400, 0x2, 0x0
            WM_TRAY = WM_USER + 20
            WM_LBUTTONUP, WM_LBUTTONDBLCLK, WM_RBUTTONUP = 0x202, 0x203, 0x205
            NIM_ADD, NIM_DELETE = 0, 2
            NIF_MESSAGE, NIF_ICON, NIF_TIP = 0x1, 0x2, 0x4

            try:
                lang = {0x0C: 'fr', 0x09: 'en', 0x07: 'de', 0x0A: 'es', 0x16: 'pt', 0x10: 'it', 0x04: 'zh', 0x11: 'ja'}.get(
                    kernel32.GetUserDefaultUILanguage() & 0xFF, 'en')
            except Exception:
                lang = 'en'
            lbl_open, lbl_quit, lbl_tip = _TRAY_LABELS.get(lang, _TRAY_LABELS['en'])

            class NOTIFYICONDATAW(ctypes.Structure):
                _fields_ = [('cbSize', wintypes.DWORD), ('hWnd', wintypes.HWND), ('uID', wintypes.UINT),
                            ('uFlags', wintypes.UINT), ('uCallbackMessage', wintypes.UINT), ('hIcon', wintypes.HICON),
                            ('szTip', wintypes.WCHAR * 128)]

            WNDPROC = ctypes.WINFUNCTYPE(LRESULT, wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM)

            class WNDCLASSW(ctypes.Structure):
                _fields_ = [('style', wintypes.UINT), ('lpfnWndProc', WNDPROC), ('cbClsExtra', ctypes.c_int),
                            ('cbWndExtra', ctypes.c_int), ('hInstance', wintypes.HINSTANCE), ('hIcon', wintypes.HICON),
                            ('hCursor', wintypes.HANDLE), ('hbrBackground', wintypes.HBRUSH),
                            ('lpszMenuName', wintypes.LPCWSTR), ('lpszClassName', wintypes.LPCWSTR)]

            user32.DefWindowProcW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
            user32.DefWindowProcW.restype = LRESULT
            user32.CreateWindowExW.argtypes = [wintypes.DWORD, wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD,
                                               ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, wintypes.HWND,
                                               wintypes.HMENU, wintypes.HINSTANCE, wintypes.LPVOID]
            user32.CreateWindowExW.restype = wintypes.HWND
            user32.RegisterClassW.argtypes = [ctypes.POINTER(WNDCLASSW)]
            user32.AppendMenuW.argtypes = [wintypes.HMENU, wintypes.UINT, ctypes.c_size_t, wintypes.LPCWSTR]
            user32.CreatePopupMenu.restype = wintypes.HMENU
            user32.TrackPopupMenu.argtypes = [wintypes.HMENU, wintypes.UINT, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                                              wintypes.HWND, ctypes.c_void_p]
            user32.SetForegroundWindow.argtypes = [wintypes.HWND]
            user32.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
            user32.LoadImageW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT, ctypes.c_int, ctypes.c_int, wintypes.UINT]
            user32.LoadImageW.restype = wintypes.HANDLE
            shell32.ExtractIconW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT]
            shell32.ExtractIconW.restype = wintypes.HICON
            shell32.Shell_NotifyIconW.argtypes = [wintypes.DWORD, ctypes.POINTER(NOTIFYICONDATAW)]

            kernel32.GetModuleHandleW.argtypes = [wintypes.LPCWSTR]
            kernel32.GetModuleHandleW.restype = wintypes.HINSTANCE
            user32.LoadIconW.argtypes = [wintypes.HINSTANCE, ctypes.c_void_p]
            user32.LoadIconW.restype = wintypes.HICON
            user32.DestroyMenu.argtypes = [wintypes.HMENU]
            user32.GetMessageW.argtypes = [ctypes.POINTER(wintypes.MSG), wintypes.HWND, wintypes.UINT, wintypes.UINT]
            user32.RegisterWindowMessageW.argtypes = [wintypes.LPCWSTR]
            hinst = kernel32.GetModuleHandleW(None)
            hicon = None
            try:
                base = os.path.dirname(os.path.abspath(sys.executable if getattr(sys, 'frozen', False) else __file__))
                for cand in (os.path.join(base, 'assets', 'logo-nom-stellio.ico'),
                             os.path.join(getattr(sys, '_MEIPASS', base), 'assets', 'logo-nom-stellio.ico')):
                    if os.path.isfile(cand):
                        hicon = user32.LoadImageW(None, cand, 1, 16, 16, 0x10)   # IMAGE_ICON, LR_LOADFROMFILE
                        if hicon:
                            break
                if not hicon and getattr(sys, 'frozen', False):
                    h = shell32.ExtractIconW(hinst, sys.executable, 0)           # icône intégrée à Stellio.exe
                    hicon = h if h and h != 1 else None
            except Exception:
                hicon = None
            if not hicon:
                hicon = user32.LoadIconW(None, 32512)                            # IDI_APPLICATION

            taskbar_created = user32.RegisterWindowMessageW('TaskbarCreated')
            nid = NOTIFYICONDATAW()
            nid.cbSize = ctypes.sizeof(NOTIFYICONDATAW)
            nid.uID = 1
            nid.uFlags = NIF_MESSAGE | NIF_ICON | NIF_TIP
            nid.uCallbackMessage = WM_TRAY
            nid.hIcon = hicon
            nid.szTip = lbl_tip[:127]

            def _safe(fn):
                threading.Thread(target=lambda: fn(), daemon=True).start()

            def _wndproc(hwnd, msg, wparam, lparam):
                try:
                    if msg == WM_TRAY:
                        if lparam in (WM_LBUTTONUP, WM_LBUTTONDBLCLK):
                            _safe(on_open)
                        elif lparam == WM_RBUTTONUP:
                            pt = wintypes.POINT()
                            user32.GetCursorPos(ctypes.byref(pt))
                            menu = user32.CreatePopupMenu()
                            user32.AppendMenuW(menu, 0, 1, lbl_open)
                            user32.AppendMenuW(menu, 0x800, 0, None)            # séparateur
                            user32.AppendMenuW(menu, 0, 2, lbl_quit)
                            user32.SetForegroundWindow(hwnd)
                            cmd = user32.TrackPopupMenu(menu, 0x0100 | 0x0020, pt.x, pt.y, 0, hwnd, None)   # TPM_RETURNCMD | TPM_RIGHTBUTTON
                            user32.PostMessageW(hwnd, WM_NULL, 0, 0)
                            user32.DestroyMenu(menu)
                            if cmd == 1:
                                _safe(on_open)
                            elif cmd == 2:
                                shell32.Shell_NotifyIconW(NIM_DELETE, ctypes.byref(nid))
                                _safe(on_quit)
                        return 0
                    if taskbar_created and msg == taskbar_created:               # l'explorateur a redémarré : on remet l'icône
                        shell32.Shell_NotifyIconW(NIM_ADD, ctypes.byref(nid))
                        return 0
                    if msg == WM_DESTROY:
                        shell32.Shell_NotifyIconW(NIM_DELETE, ctypes.byref(nid))
                        return 0
                except Exception:
                    pass
                return user32.DefWindowProcW(hwnd, msg, wparam, lparam)

            proc = WNDPROC(_wndproc)                                             # référence gardée vivante
            wc = WNDCLASSW()
            wc.lpfnWndProc = proc
            wc.hInstance = hinst
            wc.lpszClassName = 'StellioTrayWindow'
            user32.RegisterClassW(ctypes.byref(wc))
            hwnd = user32.CreateWindowExW(0, 'StellioTrayWindow', 'StellioTray', 0, 0, 0, 0, 0, None, None, hinst, None)
            if not hwnd:
                return
            nid.hWnd = hwnd
            if not shell32.Shell_NotifyIconW(NIM_ADD, ctypes.byref(nid)):
                app_logger.info("[Tray] Icône de notification non ajoutée")
                return
            msg = wintypes.MSG()
            while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))
        except Exception as ex:
            app_logger.info(f"[Tray] Icône de zone de notification indisponible: {ex}")

    threading.Thread(target=_run, name='stellio-tray', daemon=True).start()


def _lower_thread_priority():
    try:
        if sys.platform == 'win32':
            import ctypes
            THREAD_PRIORITY_BELOW_NORMAL = -1
            handle = ctypes.windll.kernel32.GetCurrentThread()
            ctypes.windll.kernel32.SetThreadPriority(handle, THREAD_PRIORITY_BELOW_NORMAL)
        else:
            tid = threading.get_native_id()
            os.setpriority(os.PRIO_PROCESS, tid, 5)
    except Exception:
        pass


_ES_CONTINUOUS = 0x80000000
_ES_SYSTEM_REQUIRED = 0x00000001
_sleep_prevention_lock = threading.Lock()
_sleep_prevention_active = False
_sleep_prevention_proc = None  


def _prevent_system_sleep(enable):
    global _sleep_prevention_active, _sleep_prevention_proc
    try:
        with _sleep_prevention_lock:
            if enable and not _sleep_prevention_active:
                if sys.platform == 'win32':
                    import ctypes
                    ctypes.windll.kernel32.SetThreadExecutionState(
                        _ES_CONTINUOUS | _ES_SYSTEM_REQUIRED
                    )
                elif sys.platform == 'darwin':
                    _sleep_prevention_proc = subprocess.Popen(['caffeinate', '-d', '-i'])
                else:
                    if shutil.which('systemd-inhibit'):
                        _sleep_prevention_proc = subprocess.Popen([
                            'systemd-inhibit', '--what=idle:sleep', '--why=Stellio: génération en cours',
                            'sleep', 'infinity'
                        ])
                    else:
                        app_logger.info("[POWER] systemd-inhibit indisponible — veille non inhibée sur ce système")
                _sleep_prevention_active = True
                app_logger.info("[POWER] Veille système inhibée (génération de miniatures en cours)")
            elif not enable and _sleep_prevention_active:
                if sys.platform == 'win32':
                    import ctypes
                    ctypes.windll.kernel32.SetThreadExecutionState(_ES_CONTINUOUS)
                elif _sleep_prevention_proc is not None:
                    _sleep_prevention_proc.terminate()
                    _sleep_prevention_proc = None
                _sleep_prevention_active = False
                app_logger.info("[POWER] Veille système ré-autorisée (génération terminée)")
    except Exception as e:
        app_logger.warning(f"[POWER] Impossible de gérer l'état de veille: {e}")


