_SOURCE_STATUS_CACHE = {}          # user_id -> (horodatage, résultat)
_SOURCE_STATUS_TTL = 10.0
_SOURCE_STATUS_TIMEOUT = 6.0


_NET_CACHE = {'t': 0.0, 'up': True}


def _network_up():
    """Étape 1 : la machine a-t-elle une connexion réseau ? (au moins une interface active avec une adresse hors boucle locale).
    Sans réseau, inutile d'attendre les délais d'expiration des partages SMB. En cas de doute, on répond « oui »."""
    now = time.time()
    if now - _NET_CACHE['t'] < 2:
        return _NET_CACHE['up']
    up = True
    try:
        import psutil
        stats = psutil.net_if_stats()
        up = False
        for name, addrs in psutil.net_if_addrs().items():
            st = stats.get(name)
            if not st or not st.isup:
                continue
            if any(a.family == socket.AF_INET and not a.address.startswith('127.') and not a.address.startswith('169.254.') for a in addrs):
                up = True
                break
    except Exception:
        up = True
    _NET_CACHE.update(t=now, up=up)
    return up


def _smb_host_reachable(path, timeout=1.5):
    """Étape 2 : le serveur répond-il sur le port SMB ? Test rapide avant d'ouvrir une session SMB."""
    host = _smb_host_of(path)
    if not host:
        return False
    try:
        with socket.create_connection((host, 445), timeout=timeout):
            return True
    except Exception:
        return False


def _check_one_source_available(source, network_up=True):
    """True si la source répond (dossier/fichier présent, partage SMB joignable). Réseau d'abord, puis serveur, puis partage."""
    try:
        stype = source['type']
        if stype == 'smb':
            if not network_up:
                return False
            unc_path = source['path'].replace('\\\\', '//').replace('\\', '/')
            if not _smb_host_reachable(unc_path):
                _smb_host_mark_down(unc_path)
                return False
            _smb_host_down.pop(_smb_host_of(unc_path), None)
            kwargs = {'connection_timeout': 4}
            config = json.loads(source['config']) if source['config'] else {}
            if config.get('username'):
                kwargs['username'] = config['username']
            if config.get('password'):
                kwargs['password'] = config['password']
            smbclient.stat(unc_path, **kwargs)
            return True
        return os.path.exists(source['path'])
    except Exception:
        return False


@app.route('/api/sources/status', methods=['GET'])
@login_required
def api_sources_status():
    """Disponibilité de chaque source (coche verte / croix rouge dans l'interface). Résultat mis en cache 10 s ;
    chaque test a un délai maximal pour qu'un partage réseau éteint ne bloque jamais la réponse."""
    user_id = session['user_id']
    now = time.time()
    cached = _SOURCE_STATUS_CACHE.get(user_id)
    if cached and now - cached[0] < _SOURCE_STATUS_TTL and not request.args.get('force'):
        return jsonify(cached[1])
    conn = get_db()
    try:
        rows = [dict(r) for r in conn.execute("SELECT id, name, type, path, config FROM sources WHERE user_id = ?", (user_id,)).fetchall()]
    finally:
        conn.close()
    results = {}
    network_up = _network_up()
    if rows:
        pool = ThreadPoolExecutor(max_workers=min(8, len(rows)))
        futures = {r['id']: pool.submit(_check_one_source_available, r, network_up) for r in rows}
        deadline = time.time() + _SOURCE_STATUS_TIMEOUT
        for r in rows:
            try:
                results[r['id']] = bool(futures[r['id']].result(timeout=max(0.1, deadline - time.time())))
            except Exception:
                results[r['id']] = False
        pool.shutdown(wait=False)
    payload = {"network": network_up, "sources": [{"id": r['id'], "name": r['name'], "type": r['type'], "available": results.get(r['id'], False)} for r in rows]}
    _SOURCE_STATUS_CACHE[user_id] = (now, payload)
    return jsonify(payload)


_SOURCE_SUGGEST_CAP = 200          
_SOURCE_SUGGEST_MAX_DEPTH = 4
_SOURCE_SUGGEST_TIME_BUDGET = 4.0  


def _count_3d_files(folder, deadline, cap=_SOURCE_SUGGEST_CAP, max_depth=_SOURCE_SUGGEST_MAX_DEPTH):
    count = 0
    base_depth = folder.rstrip('/\\').count(os.sep)
    for root, dirs, files in os.walk(folder):
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        if root.count(os.sep) - base_depth >= max_depth:
            dirs[:] = []
        for fn in files:
            if os.path.splitext(fn)[1].lower() in SUPPORTED_EXTENSIONS:
                count += 1
                if count >= cap:
                    return count, True
        if time.time() > deadline:
            return count, True
    return count, False


@app.route('/api/sources/suggestions', methods=['GET'])
@login_required
def api_source_suggestions():
    try:
        if ALLOWED_SOURCE_TYPES and 'folder' not in ALLOWED_SOURCE_TYPES:
            return jsonify({"suggestions": []}), 200
        home = Path.home()
        names = ['Downloads', 'Téléchargements', 'Documents', 'Desktop', 'Bureau', '3D Objects', 'Objets 3D',
                 '3D Models', 'Modèles 3D', 'Models', 'Impression 3D', '3D Printing', 'Printables',
                 'Thingiverse', 'MakerWorld', 'Cults', 'Bambu Studio', 'BambuStudio', 'Qidi Studio', 'QIDIStudio', 'OrcaSlicer',
                 'PrusaSlicer', 'Cura']
        candidates, seen = [], set()
        for n in names:
            p = home / n
            try:
                key = os.path.realpath(str(p)).replace('\\', '/').rstrip('/').lower()
                if key in seen or not p.is_dir():
                    continue
                seen.add(key)
                candidates.append((n, str(p)))
            except OSError:
                continue

        conn = get_db()
        try:
            rows = conn.execute("SELECT path FROM sources WHERE user_id=? AND type IN ('folder','nfs')",
                                (session['user_id'],)).fetchall()
        finally:
            conn.close()
        existing = [os.path.realpath(r['path']).replace('\\', '/').rstrip('/').lower() for r in rows if r['path']]

        def _already_covered(path):
            cur = os.path.realpath(path).replace('\\', '/').rstrip('/').lower()
            return any(cur == e or cur.startswith(e + '/') or e.startswith(cur + '/') for e in existing)

        deadline = time.time() + _SOURCE_SUGGEST_TIME_BUDGET
        out = []
        for name, path in candidates:
            if _already_covered(path):
                continue
            if time.time() > deadline:
                break
            count, capped = _count_3d_files(path, deadline)
            if count > 0:
                out.append({"name": name, "path": path, "count": count, "capped": capped})
        out.sort(key=lambda x: -x['count'])
        return jsonify({"suggestions": out[:6]}), 200
    except Exception as e:
        app_logger.warning(f"[SOURCES] Suggestions de dossiers impossibles: {e}")
        return jsonify({"suggestions": []}), 200


@app.route('/api/sources', methods=['POST'])
@login_required
def api_add_source():
    data = request.json
    name = data.get('name', '').strip()
    src_type = data.get('type')
    path = data.get('path')
    config = json.dumps(data.get('config', {}))
    user_id = session['user_id']

    if not all([src_type, path]):
        return jsonify({"error": "Champs requis"}), 400

    if src_type not in ALLOWED_SOURCE_TYPES:
        return jsonify({"error": f"Type de source '{src_type}' désactivé sur ce serveur. Types autorisés : {', '.join(sorted(ALLOWED_SOURCE_TYPES))}"}), 403

    conn = get_db()
    if not name:
        name = f"Source {len(conn.execute('SELECT id FROM sources WHERE user_id=?', (user_id,)).fetchall()) + 1}"
    try:
        conn.execute("INSERT INTO sources (user_id, name, type, path, config) VALUES (?, ?, ?, ?, ?)",
                     (user_id, name, src_type, path, config))
        conn.commit()
        invalidate_cache()

        new_sources_list = [dict(s) for s in conn.execute(
            "SELECT * FROM sources WHERE user_id = ?", (user_id,)
        ).fetchall()]
        threading.Thread(
            target=_do_background_scan,
            args=(new_sources_list, user_id),
            kwargs={'blocking': True},
            daemon=True
        ).start()

        return jsonify({"message": "Source ajoutée"}), 200
    except Exception as e:
        app_logger.error(f"[API] Erreur non gérée: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500
    finally:
        conn.close()

@app.route('/api/sources/drop', methods=['POST'])
@login_required
def api_add_sources_from_drop():
    data = request.json or {}
    paths = data.get('paths') or []
    user_id = session['user_id']

    DROPPABLE_FILE_EXTS = SUPPORTED_EXTENSIONS | IN_MEMORY_ARCHIVE_EXTS | {'.rar', '.step', '.stp', '.amf', '.ply'}

    added, skipped = [], []
    conn = get_db()
    try:
        existing_names = {r[0] for r in conn.execute("SELECT name FROM sources WHERE user_id=?", (user_id,)).fetchall()}
        for raw_path in paths:
            path = (raw_path or '').strip()
            if not path:
                continue
            if not os.path.exists(path):
                skipped.append({"path": path, "reason": "introuvable"})
                continue

            is_dir = os.path.isdir(path)
            if is_dir:
                src_type = 'folder'
            else:
                ext = os.path.splitext(path)[1].lower()
                if ext not in DROPPABLE_FILE_EXTS:
                    skipped.append({"path": path, "reason": f"extension {ext or '?'} non supportée"})
                    continue
                src_type = 'file'

            if src_type not in ALLOWED_SOURCE_TYPES:
                skipped.append({"path": path, "reason": f"type '{src_type}' désactivé sur ce serveur"})
                continue

            base_name = os.path.basename(path.rstrip('/\\')) or path
            name = base_name
            suffix = 2
            while name in existing_names:
                name = f"{base_name} ({suffix})"
                suffix += 1
            existing_names.add(name)

            try:
                conn.execute("INSERT INTO sources (user_id, name, type, path, config) VALUES (?, ?, ?, ?, ?)",
                             (user_id, name, src_type, path, '{}'))
                added.append({"path": path, "name": name, "type": src_type})
            except Exception as e:
                skipped.append({"path": path, "reason": str(e)})

        conn.commit()
    finally:
        conn.close()

    if added:
        invalidate_cache()
        conn2 = get_db()
        new_sources_list = [dict(s) for s in conn2.execute(
            "SELECT * FROM sources WHERE user_id = ?", (user_id,)
        ).fetchall()]
        conn2.close()
        threading.Thread(
            target=_do_background_scan,
            args=(new_sources_list, user_id),
            kwargs={'blocking': True},
            daemon=True
        ).start()

    return jsonify({"added": added, "skipped": skipped}), 200


@app.route('/api/files/upload-drop', methods=['POST'])
@login_required
def api_upload_dropped_files():
    try:
        user_id = session['user_id']
        uploaded_files = request.files.getlist('files')
        if not uploaded_files:
            return jsonify({"error": "Aucun fichier reçu"}), 400

        droppable_exts = SUPPORTED_EXTENSIONS | IN_MEMORY_ARCHIVE_EXTS | {'.rar', '.step', '.stp', '.amf', '.ply'}

        conn = get_db()
        try:
            dest_source_id = request.form.get('source_id', type=int)
            dest_row = None
            if dest_source_id:
                dest_row = conn.execute(
                    "SELECT id, name, path, type FROM sources WHERE id = ? AND user_id = ? AND type = 'folder'",
                    (dest_source_id, user_id)
                ).fetchone()
            if not dest_row:
                dest_row = conn.execute(
                    "SELECT id, name, path, type FROM sources WHERE user_id = ? AND type = 'folder' ORDER BY id LIMIT 1",
                    (user_id,)
                ).fetchone()

            if dest_row:
                dest_dir = dest_row['path']
                dest_source_name = dest_row['name']
            else:
                dest_dir = os.path.join(DATA_DIR, 'imports')
                os.makedirs(dest_dir, exist_ok=True)
                existing_names = {r[0] for r in conn.execute("SELECT name FROM sources WHERE user_id=?", (user_id,)).fetchall()}
                dest_source_name = 'Imports'
                suffix = 2
                while dest_source_name in existing_names:
                    dest_source_name = f"Imports ({suffix})"
                    suffix += 1
                conn.execute("INSERT INTO sources (user_id, name, type, path, config) VALUES (?, ?, 'folder', ?, '{}')",
                             (user_id, dest_source_name, dest_dir))
                conn.commit()

            saved, skipped = [], []
            for f in uploaded_files:
                original_name = secure_filename(f.filename or '') or 'fichier'
                ext = os.path.splitext(original_name)[1].lower()
                if ext not in droppable_exts:
                    skipped.append({"name": f.filename, "reason": f"extension {ext or '?'} non supportée"})
                    continue

                dest_path = os.path.join(dest_dir, original_name)
                base, extension = os.path.splitext(original_name)
                counter = 2
                while os.path.exists(dest_path):
                    dest_path = os.path.join(dest_dir, f"{base} ({counter}){extension}")
                    counter += 1

                f.save(dest_path)
                saved.append(os.path.basename(dest_path))
                journal_log('add', os.path.basename(dest_path), None, dest_path, user_id=user_id)
        finally:
            conn.close()

        if saved:
            invalidate_cache()
            conn3 = get_db()
            all_sources = [dict(s) for s in conn3.execute("SELECT * FROM sources WHERE user_id = ?", (user_id,)).fetchall()]
            conn3.close()
            threading.Thread(target=_do_background_scan, args=(all_sources, user_id), kwargs={'blocking': True}, daemon=True).start()

        return jsonify({
            "saved": saved,
            "skipped": skipped,
            "destination": dest_source_name,
        }), 200
    except Exception as e:
        app_logger.error(f"[API] Erreur api_upload_dropped_files: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


@app.route('/api/sources/<int:source_id>', methods=['PUT'])
@login_required
def api_update_source(source_id):
    data = request.json or {}

    # Choix des types de fichiers affichés pour cette source (liste de clés de SOURCE_TYPE_GROUPS ; vide/absent = tous)
    if 'extensions' in data:
        groups = data.get('extensions')
        if groups is not None and not isinstance(groups, list):
            return jsonify({"error": "Paramètre 'extensions' invalide"}), 400
        keys = [str(g).lower().lstrip('.') for g in (groups or [])]
        keys = [('step' if k == 'stp' else k) for k in keys]
        if any(k not in SOURCE_TYPE_GROUPS for k in keys):
            return jsonify({"error": "Type de fichier inconnu"}), 400
        keys = sorted(set(keys))
        if groups is not None and len(groups) > 0 and not keys:
            return jsonify({"error": "Choisissez au moins un type de fichier"}), 400
        conn = get_db()
        try:
            row = conn.execute("SELECT * FROM sources WHERE id = ? AND user_id = ?", (source_id, session['user_id'])).fetchone()
            if not row:
                return jsonify({"error": "Source introuvable"}), 404
            try:
                cfg = json.loads(row['config']) if row['config'] else {}
            except Exception:
                cfg = {}
            if keys and set(keys) != set(SOURCE_TYPE_GROUPS):
                cfg['extensions'] = [e for k in keys for e in SOURCE_TYPE_GROUPS[k]]
            else:
                cfg.pop('extensions', None)
            conn.execute("UPDATE sources SET config = ? WHERE id = ? AND user_id = ?",
                         (json.dumps(cfg), source_id, session['user_id']))
            conn.commit()
            # Le cache n'est PAS supprimé : _drop_disabled_type_files masque tout de suite les types
            # désactivés à la lecture ; le rescan en arrière-plan ne sert qu'à (ré)ajouter ceux réactivés.
            all_sources = [dict(s) for s in conn.execute("SELECT * FROM sources WHERE user_id = ?", (session['user_id'],)).fetchall()]
        finally:
            conn.close()
        threading.Thread(target=_do_background_scan, args=(all_sources, session['user_id']),
                         kwargs={'blocking': True}, daemon=True).start()
        return jsonify({"message": "Types de fichiers mis à jour"}), 200

    new_name = (data.get('name') or '').strip()
    if not new_name:
        return jsonify({"error": "Nom requis"}), 400

    conn = get_db()
    try:
        conn.execute("UPDATE sources SET name = ? WHERE id = ? AND user_id = ?",
                     (new_name, source_id, session['user_id']))
        conn.commit()
        invalidate_cache()
    finally:
        conn.close()
    return jsonify({"message": "Source mise à jour"}), 200

@app.route('/api/sources/<int:source_id>', methods=['DELETE'])
@login_required
def api_delete_source(source_id):
    conn = get_db()
    try:
        deleted_row = conn.execute(
            "SELECT name, type, path, config FROM sources WHERE id = ? AND user_id = ?",
            (source_id, session['user_id'])
        ).fetchone()
        conn.execute("DELETE FROM sources WHERE id = ? AND user_id = ?",
                     (source_id, session['user_id']))
        conn.commit()
        remaining_sources = [dict(s) for s in conn.execute(
            "SELECT * FROM sources WHERE user_id = ?", (session['user_id'],)
        ).fetchall()]
    finally:
        conn.close()
    # Fichiers déjà connus des sources restantes : si l'une d'elles est injoignable, on les garde au lieu de les perdre.
    _prev_cached = []
    try:
        _keep = {s['name'] for s in remaining_sources}
        _prev_cached = [pf for pf in (load_file_cache() or []) if pf.get('source') in _keep]
    except Exception:
        _prev_cached = []
    invalidate_cache()

    def _rescan_after_delete(sources):
        acquired = _background_scan_running.acquire(blocking=True, timeout=10)
        if acquired:
            try:
                app_logger.info("[DELETE] Rescan post-suppression source...")
                all_files = []
                _failed = set()
                for source in sources:
                    try:
                        if source['type'] == 'folder':
                            if not os.path.exists(source['path']):
                                _failed.add(source['name'])
                                continue
                            all_files.extend(_filter_files_for_source(source, scan_local_folder(source['path'])))
                        elif source['type'] == 'smb':
                            try:
                                smbclient.reset_connection_cache()
                            except Exception:
                                pass
                            unc_path = source['path'].replace('\\\\', '//').replace('\\', '/')
                            kwargs = {'connection_timeout': 8}
                            config = json.loads(source['config']) if source['config'] else {}
                            if config.get('username'):
                                kwargs['username'] = config['username']
                            if config.get('password'):
                                kwargs['password'] = config['password']
                            all_files.extend(_filter_files_for_source(source, scan_smb_folder_recursive(unc_path, '', kwargs, source['name'])))
                    except Exception as e:
                        _failed.add(source.get('name'))
                        app_logger.warning(f"[DELETE] Erreur source {source.get('name')}: {e}")
                if _failed:
                    all_files.extend(pf for pf in _prev_cached if pf.get('source') in _failed)
                save_file_cache(all_files, sources)
                app_logger.info(f"[DELETE] Cache mis à jour : {len(all_files)} fichiers")
            finally:
                _background_scan_running.release()
        else:
            app_logger.warning("[DELETE] Lock background non acquis, cache invalidé sans rescan")

    threading.Thread(target=_rescan_after_delete, args=(remaining_sources,), daemon=True).start()
    return jsonify({
        "message": "Source supprimée",
        "undo": {
            "name": deleted_row['name'], "type": deleted_row['type'],
            "path": deleted_row['path'], "config": json.loads(deleted_row['config']) if deleted_row['config'] else {},
        } if deleted_row else None,
    }), 200


