# --- Découpe d'un fichier multi-plateaux (3MF) en un fichier par plateau (v0.7.5) ---
_PLATE_META_FILE_RE = re.compile(r'^(metadata/)((?:plate|plate_no_light|top|pick)_)(\d+)(\.[A-Za-z0-9.]+)$', re.I)


def _unique_file_path(directory, base, ext):
    """Chemin libre `directory/base+ext` (suffixe _2, _3… si le nom existe déjà)."""
    candidate = os.path.join(directory, base + ext)
    n = 2
    while os.path.exists(candidate):
        candidate = os.path.join(directory, f"{base}_{n}{ext}")
        n += 1
    return candidate


def _rewrite_3mf_model_settings(data, plate_key, keep_ids, other_ids, renamed):
    """Ne garde dans model_settings.config que le plateau voulu (renuméroté 1) et ses objets."""
    import xml.etree.ElementTree as _ET
    root = _safe_xml_parse(io.BytesIO(data)).getroot()
    parent = {c: p for p in root.iter() for c in p}
    lower_map = {k.lower(): v for k, v in renamed.items()}

    for obj in list(root.findall('object')):
        if str(obj.get('id')) in other_ids:
            root.remove(obj)

    for i, plate_el in enumerate(list(root.findall('.//plate'))):
        pid_meta = None
        pid = None
        for meta in plate_el.findall('metadata'):
            if meta.get('key') == 'plater_id':
                pid_meta = meta
                pid = meta.get('value')
                break
        key = pid or str(i + 1)
        if key != str(plate_key):
            parent[plate_el].remove(plate_el)
            continue
        if pid_meta is not None:
            pid_meta.set('value', '1')
        else:
            _ET.SubElement(plate_el, 'metadata', {'key': 'plater_id', 'value': '1'})
        for meta in plate_el.findall('metadata'):
            if (meta.get('key') or '').endswith('_file') and meta.get('value'):
                old = meta.get('value').lstrip('/').lower()
                if old in lower_map:
                    meta.set('value', lower_map[old] or '')

    for assemble in root.findall('assemble'):
        for item in list(assemble):
            if str(item.get('object_id')) in other_ids:
                assemble.remove(item)

    return _ET.tostring(root, encoding='utf-8', xml_declaration=True)


def _rewrite_3mf_build_items(data, keep_ids):
    """Retire de <build> les objets des autres plateaux (édition textuelle : préserve les espaces de noms)."""
    text = data.decode('utf-8-sig')
    kept = [0]

    def _filter_block(m):
        def _item(im):
            oid = re.search(r'\bobjectid="(\d+)"', im.group(0))
            if oid and oid.group(1) in keep_ids:
                kept[0] += 1
                return im.group(0)
            return ''
        return re.sub(r'<item\b[^>]*?/>', _item, m.group(0))

    new_text = re.sub(r'<build\b.*?</build>', _filter_block, text, flags=re.S)
    if kept[0] == 0:
        raise RuntimeError("Aucun objet de ce plateau trouvé dans le modèle 3MF")
    return new_text.encode('utf-8')


def _rewrite_3mf_xml_parts(data, renamed, tag_attr):
    """Met à jour les relations (.rels) ou les types de contenu après suppression/renommage de fichiers."""
    import xml.etree.ElementTree as _ET
    try:
        root = _safe_xml_parse(io.BytesIO(data)).getroot()
    except Exception:
        return data
    lower_map = {k.lower(): v for k, v in renamed.items()}
    changed = False
    for el in list(root):
        target = el.get(tag_attr) or ''
        key = target.lstrip('/').lower()
        if key in lower_map:
            new_name = lower_map[key]
            if new_name is None:
                root.remove(el)
            else:
                el.set(tag_attr, ('/' if target.startswith('/') else '') + new_name)
            changed = True
    if not changed:
        return data
    ns = root.tag.split('}')[0].lstrip('{') if root.tag.startswith('{') else ''
    if ns:
        _ET.register_namespace('', ns)
    return _ET.tostring(root, encoding='utf-8', xml_declaration=True)


def _split_3mf_plate_to_3mf(src_path, plate_key, plates, dest_path):
    """Écrit un 3MF autonome ne contenant que le plateau `plate_key` (devenu plateau 1)."""
    keep_ids = {str(x) for x in plates[plate_key]}
    other_ids = set()
    for k, ids in plates.items():
        if k != plate_key:
            other_ids |= {str(x) for x in ids}
    other_ids -= keep_ids

    with zipfile.ZipFile(src_path, 'r') as zin:
        names = zin.namelist()
        renamed = {}
        for n in names:
            m = _PLATE_META_FILE_RE.match(n)
            if m:
                renamed[n] = (f"{m.group(1)}{m.group(2)}1{m.group(4)}"
                              if m.group(3) == str(plate_key) else None)
            elif n.lower() == 'metadata/slice_info.config':
                renamed[n] = None  # infos de découpe de tous les plateaux : régénérées par le slicer

        ordered = sorted(names, key=lambda n: 0 if n == '[Content_Types].xml' else 1)
        with zipfile.ZipFile(dest_path, 'w', zipfile.ZIP_DEFLATED, compresslevel=1) as zout:
            for n in ordered:
                if n.endswith('/'):
                    continue
                new_name = renamed.get(n, n)
                if new_name is None:
                    continue
                content = zin.read(n)
                low = n.lower()
                if low.endswith('model_settings.config'):
                    content = _rewrite_3mf_model_settings(content, plate_key, keep_ids, other_ids, renamed)
                elif low == '3d/3dmodel.model':
                    content = _rewrite_3mf_build_items(content, keep_ids)
                elif low.endswith('.rels'):
                    content = _rewrite_3mf_xml_parts(content, renamed, 'Target')
                elif n == '[Content_Types].xml':
                    content = _rewrite_3mf_xml_parts(content, renamed, 'PartName')
                zout.writestr(new_name, content)


def _split_3mf_plate_to_stl(src_path, plate_index, dest_path):
    mesh = load_3mf_mesh(src_path, plate_index=plate_index)
    if mesh is None or getattr(mesh, 'is_empty', False) or len(getattr(mesh, 'vertices', [])) == 0:
        raise RuntimeError(f"Plateau {plate_index} vide : aucun maillage à exporter")
    mesh.export(dest_path, file_type='stl')


# Découpe d'un 3MF multi-plateaux : tâche de fond avec avancement, pour que l'interface affiche « plateau 3 sur 6 »
# au lieu d'un simple sablier (une découpe en STL ou d'un gros 3MF peut prendre plusieurs secondes par plateau).
_split_jobs = {}
_split_jobs_lock = threading.Lock()
SPLIT_JOB_TTL_S = 900


class _JobCancelled(Exception):
    """Levée quand l'utilisateur annule une tâche de fond (découpe, conversion en lot)."""


_convert_jobs = {}  # tâches de conversion en lot (même verrou et même durée de vie que les découpes)


def _purge_split_jobs():
    now = time.time()
    with _split_jobs_lock:
        for registry in (_split_jobs, _convert_jobs):
            for jid in [j for j, v in registry.items() if v.get('finished') and now - v['finished'] > SPLIT_JOB_TTL_S]:
                registry.pop(jid, None)


def _run_split_plates(file_path, fmt, plates, keys, job=None):
    """Découpe tout-ou-rien d'un 3MF multi-plateaux. Si `job` est fourni, y inscrit le plateau en cours et le nombre de
    plateaux terminés. Renvoie la liste des fichiers créés ; en cas d'erreur, supprime ceux déjà créés et relève l'erreur."""
    created = []
    base_dir = os.path.dirname(file_path)
    base_name = os.path.splitext(os.path.basename(file_path))[0]
    try:
        for idx, key in enumerate(keys, start=1):
            if job is not None:
                with _split_jobs_lock:
                    if job.get('cancel'):
                        raise _JobCancelled()
                    job['current'] = idx
            dest = _unique_file_path(base_dir, f"{base_name}_plateau_{idx}", '.' + fmt)
            created.append(dest)
            if fmt == '3mf':
                _split_3mf_plate_to_3mf(file_path, key, plates, dest)
            else:
                _split_3mf_plate_to_stl(file_path, idx, dest)
            if job is not None:
                with _split_jobs_lock:
                    job['done'] = idx
    except Exception:
        for p in created:  # tout ou rien : on ne laisse pas de découpe partielle
            try:
                if os.path.exists(p):
                    os.remove(p)
            except OSError:
                pass
        raise
    _rescan_sources_in_background()
    return created


@app.route('/api/files/split-plates', methods=['POST'])
@login_required
def api_split_plates():
    try:
        data = request.get_json(silent=True) or {}
        file_path = (data.get('file_path') or '').strip()
        fmt = (data.get('format') or '3mf').lower().strip('.')
        if fmt not in ('stl', '3mf'):
            return jsonify({"error": "Format invalide (stl ou 3mf)"}), 400
        if not file_path:
            return jsonify({"error": "Chemin requis"}), 400
        if '::' in file_path or is_virtual_archive_path(file_path):
            return jsonify({"error": "Découpe impossible pour un fichier situé dans une archive : extrais-le d'abord"}), 400
        if '..' in file_path.replace('\\', '/').split('/'):
            return jsonify({"error": "Chemin invalide"}), 400
        if os.name == 'nt':
            file_path = file_path.replace('/', '\\')
        if not os.path.isfile(file_path):
            return jsonify({"error": "Fichier non trouvé"}), 404
        if not _is_path_within_sources(file_path, session['user_id']):
            app_logger.warning(f"[SECURITY] Tentative de découpe hors sources: {file_path}")
            return jsonify({"error": "Ce fichier n'appartient à aucune source configurée"}), 403
        if os.path.splitext(file_path)[1].lower() != '.3mf':
            return jsonify({"error": "Seuls les fichiers 3MF multi-plateaux peuvent être découpés"}), 400

        plates = _parse_3mf_plate_object_ids(file_path)
        if not plates:
            return jsonify({"error": "Ce fichier ne contient qu'un seul plateau"}), 400
        keys = sorted(plates.keys(), key=lambda k: (len(k), k))
        user_id = session['user_id']

        if data.get('async'):
            _purge_split_jobs()
            with _split_jobs_lock:
                for jid, v in _split_jobs.items():   # déjà en cours pour ce fichier : on rend la même tâche
                    if v.get('state') == 'running' and v.get('user_id') == user_id and v.get('path') == file_path and v.get('fmt') == fmt:
                        return jsonify({"job_id": jid, "total": v['total']}), 202
                job_id = uuid.uuid4().hex
                job = {'user_id': user_id, 'path': file_path, 'fmt': fmt, 'state': 'running', 'done': 0, 'current': 1,
                       'total': len(keys), 'name': os.path.basename(file_path), 'finished': None}
                _split_jobs[job_id] = job

            def _runner():
                try:
                    created = _run_split_plates(file_path, fmt, plates, keys, job)
                    names = [os.path.basename(p) for p in created]
                    app_logger.info(f"[SPLIT] {os.path.basename(file_path)} → {len(created)} fichier(s) {fmt.upper()}: {names}")
                    journal_log('split', os.path.basename(file_path), file_path, os.path.dirname(created[0]) if created else None,
                                detail=f"{len(created)} {fmt.upper()}", user_id=user_id)
                    with _split_jobs_lock:
                        job.update(state='done', files=names, count=len(names), finished=time.time())
                except _JobCancelled:
                    app_logger.info(f"[SPLIT] Annulée par l'utilisateur : {os.path.basename(file_path)} (fichiers déjà créés supprimés)")
                    with _split_jobs_lock:
                        job.update(state='cancelled', finished=time.time())
                except Exception as e:
                    app_logger.error(f"[SPLIT] Erreur: {e}")
                    import traceback
                    app_logger.error(traceback.format_exc())
                    with _split_jobs_lock:
                        job.update(state='error', error=f"Découpe impossible : {e}", finished=time.time())

            threading.Thread(target=_runner, daemon=True, name='split-plates').start()
            return jsonify({"job_id": job_id, "total": len(keys)}), 202

        created = _run_split_plates(file_path, fmt, plates, keys)
        names = [os.path.basename(p) for p in created]
        app_logger.info(f"[SPLIT] {os.path.basename(file_path)} → {len(created)} fichier(s) {fmt.upper()}: {names}")
        journal_log('split', os.path.basename(file_path), file_path, os.path.dirname(created[0]) if created else None,
                    detail=f"{len(created)} {fmt.upper()}")
        return jsonify({"success": True, "count": len(created), "files": names,
                        "message": f"{len(created)} fichiers créés"}), 200
    except Exception as e:
        app_logger.error(f"[SPLIT] Erreur: {e}")
        import traceback
        app_logger.error(traceback.format_exc())
        return jsonify({"error": f"Découpe impossible : {e}"}), 500


@app.route('/api/files/split-plates/<job_id>', methods=['GET'])
@login_required
def api_split_plates_status(job_id):
    with _split_jobs_lock:
        job = _split_jobs.get(job_id)
        if not job or job.get('user_id') != session['user_id']:
            return jsonify({"error": "Tâche introuvable"}), 404
        out = {k: job.get(k) for k in ('state', 'done', 'current', 'total', 'name', 'count', 'files', 'error')}
    return jsonify(out)


@app.route('/api/files/split-plates/<job_id>/cancel', methods=['POST'])
@login_required
def api_split_plates_cancel(job_id):
    """Demande l'arrêt d'une découpe : le plateau en cours se termine, puis tout ce qui a été créé est supprimé."""
    with _split_jobs_lock:
        job = _split_jobs.get(job_id)
        if not job or job.get('user_id') != session['user_id']:
            return jsonify({"error": "Tâche introuvable"}), 404
        if job.get('state') == 'running':
            job['cancel'] = True
    return jsonify({"success": True})


PLATE_SPLIT_DIRNAME = '.stellio_plateaux'  # sous-dossier masqué des plateaux séparés (projets) : hors bibliothèque et hors sources


def _is_hidden_plate_path(path):
    return isinstance(path, str) and f'/{PLATE_SPLIT_DIRNAME}/' in path.replace('\\', '/')


def _thumb_base_path(file_path):
    """Chemin (sans extension) de la miniature d'un fichier : même clé que /api/thumb et le scan."""
    return os.path.join(THUMBNAILS_DIR, hashlib.md5(file_path.replace('\\', '/').encode()).hexdigest())


def _has_thumb_on_disk(file_path):
    base = _thumb_base_path(file_path)
    return any(os.path.exists(base + ext) for ext in ('.webp', '.png', '.jpg'))


def _write_thumb_from_3mf_preview(model_path):
    """Miniature instantanée d'un 3MF à partir de l'aperçu déjà embarqué par le slicer (Metadata/plate_1.png),
    sans rendu 3D (le rendu complet prend plusieurs secondes par fichier). Renvoie True si la miniature existe."""
    try:
        if _has_thumb_on_disk(model_path):
            return True
        img = _extract_3mf_embedded_preview(model_path)
        if img is None:
            return False
        os.makedirs(THUMBNAILS_DIR, exist_ok=True)
        thumb_path = _thumb_base_path(model_path) + '.webp'
        tmp_path = thumb_path + '.tmp'
        img.save(tmp_path, 'WEBP', quality=85)
        os.replace(tmp_path, thumb_path)
        return True
    except Exception as e:
        app_logger.info(f"[PROJETS] Aperçu embarqué inutilisable pour {os.path.basename(model_path)}: {e}")
        return False


def _hide_dir_on_windows(path):
    if os.name == 'nt':
        try:
            import ctypes
            ctypes.windll.kernel32.SetFileAttributesW(str(path), 0x02)
        except Exception:
            pass


def _rescan_sources_in_background():
    """Rescan des sources dans un thread, sans bloquer la requête ni supprimer le cache de la bibliothèque.

    Évite `invalidate_cache()` : sans cache, le prochain GET /api/files lancerait un scan complet bloquant
    (gel de l'interface). Les nouveaux fichiers apparaissent dès la fin du scan et leurs miniatures sont
    ensuite générées en arrière-plan par la file habituelle (`_queue_thumb_task`, priorité basse)."""
    def _run():
        try:
            _lower_thread_priority()
            conn = get_db()
            try:
                srcs = [dict(x) for x in conn.execute("SELECT * FROM sources").fetchall()]
            finally:
                conn.close()
            if srcs:
                _do_background_scan(srcs, None, blocking=True)
        except Exception as e:
            app_logger.warning(f"[SCAN] Rescan en arrière-plan échoué: {e}")
    threading.Thread(target=_run, daemon=True).start()


def _expand_multiplate_3mf_for_project(file_path, user_id):
    """Ajout à un projet : un 3MF multi-plateaux est remplacé par un 3MF autonome par plateau.

    Même découpe que /api/files/split-plates (format 3MF), fichiers créés à côté de l'original
    et nommés <nom>_plateau_N.3mf. Les fichiers déjà créés par un ajout précédent sont réutilisés
    (pas de doublons). Renvoie la liste des chemins à ajouter au projet (même style de séparateurs
    que `file_path`), ou None si le fichier n'est pas concerné : il est alors ajouté tel quel."""
    created = []
    try:
        if not isinstance(file_path, str) or os.path.splitext(file_path)[1].lower() != '.3mf':
            return None
        if '::' in file_path or is_virtual_archive_path(file_path):
            return None
        if '..' in file_path.replace('\\', '/').split('/'):
            return None
        real = file_path.replace('/', '\\') if os.name == 'nt' else file_path
        if not os.path.isfile(real) or not _is_path_within_sources(real, user_id):
            return None
        plates = _parse_3mf_plate_object_ids(real)
        if not plates:
            return None
        keys = sorted(plates.keys(), key=lambda k: (len(k), k))
        base_dir = os.path.dirname(real)
        base_name = os.path.splitext(os.path.basename(real))[0]
        hidden_dir = os.path.join(base_dir, PLATE_SPLIT_DIRNAME)
        keep_slashes = '\\' not in file_path
        result = []
        for idx, key in enumerate(keys, start=1):
            fname = f"{base_name}_plateau_{idx}.3mf"
            dest = os.path.join(hidden_dir, fname)
            legacy = os.path.join(base_dir, fname)  # plateaux créés à côté de l'original par une version précédente
            if os.path.isfile(dest):
                chosen = dest
            elif os.path.isfile(legacy):
                chosen = legacy
            else:
                if not os.path.isdir(hidden_dir):
                    os.makedirs(hidden_dir, exist_ok=True)
                    _hide_dir_on_windows(hidden_dir)
                _split_3mf_plate_to_3mf(real, key, plates, dest)
                created.append(dest)
                chosen = dest
            if not _has_thumb_on_disk(chosen) and not _write_thumb_from_3mf_preview(chosen):
                # pas d'aperçu embarqué : rendu 3D en arrière-plan, en priorité haute
                _queue_thumb_task(chosen, _thumb_base_path(chosen) + '.webp', priority='high')
            result.append(chosen.replace('\\', '/') if keep_slashes else chosen)
        app_logger.info(f"[PROJETS] {os.path.basename(real)} : {len(keys)} plateaux → {len(keys)} fichiers 3MF "
                        f"({len(created)} créé(s), {len(keys) - len(created)} réutilisé(s)) dans {PLATE_SPLIT_DIRNAME}")
        return result
    except Exception as e:
        for p in created:  # tout ou rien : pas de découpe partielle
            try:
                if os.path.exists(p):
                    os.remove(p)
            except OSError:
                pass
        app_logger.error(f"[PROJETS] Découpe multi-plateaux impossible, fichier ajouté tel quel : {e}")
        return None


def _expand_project_file_items(files, user_id):
    """Liste [(chemin, quantité)] prête à insérer : chaque 3MF multi-plateaux est remplacé par ses plateaux."""
    out = []
    seen = set()
    for item in files or []:
        file_path = item.get('path') if isinstance(item, dict) else item
        if not file_path:
            continue
        try:
            qty = max(1, int(item.get('quantity', 1))) if isinstance(item, dict) else 1
        except (TypeError, ValueError):
            qty = 1
        for path in (_expand_multiplate_3mf_for_project(file_path, user_id) or [file_path]):
            if path not in seen:
                seen.add(path)
                out.append((path, qty))
    return out


@app.route('/api/ui/activity', methods=['POST'])
@login_required
def api_ui_activity():
    """Signal d'activité envoyé par l'interface (au plus toutes les 2 s) : met les rendus de miniatures en pause."""
    global _last_user_activity
    _last_user_activity = time.time()
    return '', 204


@app.route('/api/thumb', methods=['GET'])
@login_required
def api_get_thumb():
    file_path = request.args.get('path')
    if not file_path:
        return jsonify({"error": "Chemin requis"}), 400

    if '&t=' in file_path:
        file_path = file_path.split('&t=')[0]

    normalized_path = file_path.replace('\\', '/')
    thumb_filename = hashlib.md5(normalized_path.encode()).hexdigest()
    thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename)

    for ext in ['.webp', '.png', '.jpg']:
        img_path = thumb_path + ext
        if os.path.exists(img_path):
            mimetype = {'.webp': 'image/webp', '.png': 'image/png', '.jpg': 'image/jpeg'}[ext]
            return send_file(img_path, mimetype=mimetype)

    return jsonify({"error": "Miniature non trouvée"}), 404

MAX_THUMB_FALLBACK_RETRIES = 3

_pending_thumb_lock = threading.Lock()
_pending_thumb_updates = {}
_last_thumb_flush = 0.0
THUMB_CACHE_BATCH_SIZE = 25
THUMB_CACHE_FLUSH_INTERVAL = 2.0  

def update_cache_thumb_status(file_path, has_thumb, is_fallback=False, give_up=False):
    """give_up : le rendu a dépassé son délai. On garde la miniature de remplacement et on ne le relance plus tout seul
    (sinon le superviseur de couverture le remettait en file à chaque passage, avec le même résultat à chaque fois)."""
    global _last_thumb_flush
    with _pending_thumb_lock:
        _pending_thumb_updates[file_path] = (has_thumb, is_fallback, give_up)
        should_flush = (
            len(_pending_thumb_updates) >= THUMB_CACHE_BATCH_SIZE
            or (time.time() - _last_thumb_flush) >= THUMB_CACHE_FLUSH_INTERVAL
        )
    if should_flush:
        flush_pending_thumb_updates()

def flush_pending_thumb_updates():
    global _last_thumb_flush
    with _pending_thumb_lock:
        if not _pending_thumb_updates:
            return
        updates = dict(_pending_thumb_updates)
        _pending_thumb_updates.clear()
        _last_thumb_flush = time.time()
    try:
        if not os.path.exists(CACHE_FILE):
            return
        with cache_file_lock:
            with open(CACHE_FILE, 'r', encoding='utf-8') as f:
                cache = json.load(f)
            if 'files' in cache and isinstance(cache['files'], list):
                for f in cache['files']:
                    upd = updates.get(f.get('path'))
                    if upd is None:
                        continue
                    has_thumb, is_fallback, give_up = upd
                    f['has_thumb'] = has_thumb
                    if is_fallback:
                        f['thumb_fallback'] = True
                        f['thumb_fallback_retries'] = (MAX_THUMB_FALLBACK_RETRIES if give_up
                                                       else f.get('thumb_fallback_retries', 0) + 1)
                    else:
                        f.pop('thumb_fallback', None)
                        f.pop('thumb_fallback_retries', None)
            tmp_path = CACHE_FILE + '.tmp'
            with open(tmp_path, 'w', encoding='utf-8') as f:
                json.dump(cache, f, ensure_ascii=False, separators=(',', ':'))
            _atomic_replace(tmp_path, CACHE_FILE)
    except Exception as e:
        app_logger.info(f"[CACHE] Erreur flush thumb status: {e}")

def pregenerate_thumbnails_on_startup(limit=90):
    app_logger.info("[THUMBS] 🔄 Pré-génération des miniatures au démarrage...")
    conn = get_db()
    try:
        sources = conn.execute("SELECT * FROM sources").fetchall()
    finally:
        conn.close()

    to_process = []
    for source in sources:
        if len(to_process) >= limit:
            break
        try:
            if source['type'] == 'folder' and os.path.exists(source['path']):
                _src_exts = _source_allowed_exts(source)
                _src_tuple = tuple(sorted(_src_exts)) if _src_exts else SUPPORTED_EXTENSIONS_TUPLE
                for root, dirs, files in os.walk(source['path']):
                    dirs[:] = [d for d in dirs if d != PLATE_SPLIT_DIRNAME]
                    for f in sorted(files, key=str.lower):
                        if len(to_process) >= limit:
                            break
                        if f.lower().endswith(_src_tuple):
                            file_path = os.path.join(root, f).replace('\\', '/')
                            normalized_path = file_path
                            thumb_filename = hashlib.md5(normalized_path.encode()).hexdigest()
                            thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename + '.webp')
                            if not os.path.exists(thumb_path) and not _is_ignored_recently(file_path):
                                to_process.append((file_path, thumb_path))
                    break
        except Exception as e:
            app_logger.info(f"[THUMBS] Erreur source {source['name']}: {e}")

    def _generate_one(item):
        file_path, thumb_path = item
        for _ in range(3600):   # pause demandée par l'utilisateur : on attend la reprise (jusqu'à 1 h)
            if not _thumb_paused:
                break
            time.sleep(1)
        for _ in range(60):   # mémoire presque épuisée : on attend (jusqu'à 2 min) plutôt que de faire planter la machine
            if not _low_memory():
                break
            time.sleep(2)
        try:
            app_logger.info(f"[THUMBS] Génération: {os.path.basename(file_path)}")
            success = generate_thumbnail_pyrender(file_path, thumb_path)
            _trim_memory_if_needed()
            if success:
                update_cache_thumb_status(file_path, True)
                return True
            create_fallback_thumbnail(thumb_path)
            update_cache_thumb_status(file_path, True, is_fallback=True,
                                      give_up=_consume_thumb_timeout(file_path))
            return False
        except Exception as e:
            app_logger.info(f"[THUMBS] Erreur génération {os.path.basename(file_path)}: {e}")
            return False

    generated = 0
    if to_process:
        with ThreadPoolExecutor(max_workers=max(1, min(NUM_THUMB_WORKERS, _thumb_allowed_workers()))) as pool:
            results = list(pool.map(_generate_one, to_process))
        generated = sum(1 for r in results if r)

    app_logger.info(f"[THUMBS] ✅ {generated}/{len(to_process)} miniatures pré-générées")

