@app.route('/api/thumb/check', methods=['POST'])
@login_required
def api_check_thumb():
    data = request.json or {}

    paths = data.get('paths') or ([data.get('path')] if data.get('path') else [])
    if not paths:
        return jsonify({"exists": False}), 400

    if data.get('path') and not data.get('paths'):
        file_path = data['path']
        normalized = file_path.replace('\\', '/')
        thumb_filename = hashlib.md5(normalized.encode()).hexdigest()
        thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename)
        for ext in ['.webp', '.png', '.jpg']:
            if os.path.exists(thumb_path + ext):
                return jsonify({
                    "exists": True, "type": "cached",
                    "url": f"/api/thumb?path={file_path}",
                    "timestamp": int(os.path.getmtime(thumb_path + ext))
                })
        return jsonify({"exists": False})

    results = []
    for file_path in paths:
        normalized = file_path.replace('\\', '/')
        thumb_filename = hashlib.md5(normalized.encode()).hexdigest()
        thumb_path_base = os.path.join(THUMBNAILS_DIR, thumb_filename)
        found = False
        for ext in ['.webp', '.png', '.jpg']:
            full = thumb_path_base + ext
            if os.path.exists(full):
                results.append({
                    "path": file_path,
                    "ready": True,
                    "url": f"/api/thumb?path={file_path}",
                    "thumb_mtime": int(os.path.getmtime(full))
                })
                found = True
                break
        if not found:
            results.append({"path": file_path, "ready": False})

    return jsonify({"results": results})

def reconcile_thumbnails_with_disk():
    global _thumb_reconciled_this_run
    _thumb_reconciled_this_run = True

    result = {'total': 0, 'with_thumb': 0, 'without_thumb': 0, 'requeued': 0}
    if not os.path.exists(CACHE_FILE):
        return result

    try:
        with cache_file_lock:
            with open(CACHE_FILE, 'r', encoding='utf-8') as f:
                cache = json.load(f)
            files = cache.get('files', [])

            try:
                existing_thumbs = set(os.listdir(THUMBNAILS_DIR))
            except Exception:
                existing_thumbs = None

            if existing_thumbs is not None:
                requeued = 0
                changed = False
                seen_paths = set()
                files_ordered = sorted(files, key=lambda f: os.path.basename(f.get('path', '')).lower())
                for f in files_ordered:
                    normalized = f['path'].replace('\\', '/')
                    thumb_filename = hashlib.md5(normalized.encode()).hexdigest()
                    real_has_thumb = (
                        (thumb_filename + '.webp') in existing_thumbs or
                        (thumb_filename + '.jpg') in existing_thumbs
                    )
                    if f.get('has_thumb') and not real_has_thumb:
                        f['has_thumb'] = False
                        f.pop('thumb_mtime', None)
                        changed = True
                        if not _is_ignored_recently(normalized) and normalized not in seen_paths:
                            seen_paths.add(normalized)
                            thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename + '.webp')
                            if _queue_thumb_task(normalized, thumb_path, priority='low'):
                                requeued += 1
                    elif f.get('thumb_fallback') and f.get('thumb_fallback_retries', 0) < MAX_THUMB_FALLBACK_RETRIES:
                        if not _is_ignored_recently(normalized) and normalized not in seen_paths:
                            seen_paths.add(normalized)
                            thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename + '.webp')
                            try:
                                if os.path.exists(thumb_path):
                                    os.remove(thumb_path)
                            except Exception:
                                pass
                            if _queue_thumb_task(normalized, thumb_path, priority='low'):
                                requeued += 1
                    elif not f.get('has_thumb') and not real_has_thumb:
                        if not _is_ignored_recently(normalized) and normalized not in seen_paths:
                            seen_paths.add(normalized)
                            thumb_path = os.path.join(THUMBNAILS_DIR, thumb_filename + '.webp')
                            if _queue_thumb_task(normalized, thumb_path, priority='low'):
                                requeued += 1
                if changed:
                    try:
                        tmp_path = CACHE_FILE + '.tmp'
                        with open(tmp_path, 'w', encoding='utf-8') as f_out:
                            json.dump(cache, f_out, indent=2, ensure_ascii=False)
                        _atomic_replace(tmp_path, CACHE_FILE)
                    except Exception as e:
                        app_logger.info(f"[THUMBS] Échec sauvegarde après réconciliation: {e}")
                if requeued:
                    app_logger.info(f"[THUMBS] 🔄 Comparaison fichiers/miniatures : {requeued} manquante(s) — génération lancée")
                    _thumb_session_note_start(requeued)
                result['requeued'] = requeued

            for file_entry in files:
                if file_entry.get('has_thumb'):
                    result['with_thumb'] += 1
                else:
                    result['without_thumb'] += 1
            result['total'] = result['with_thumb'] + result['without_thumb']
    except Exception as e:
        app_logger.info(f"[THUMBS] Erreur réconciliation: {e}")

    return result


JOURNAL_UNDOABLE = ('rename', 'move', 'delete')


def _journal_entry_can_undo(row):
    if row['undone'] or row['action'] not in JOURNAL_UNDOABLE:
        return False
    try:
        if not row['to_path'] or not os.path.exists(row['to_path']):
            return False
        if row['action'] in ('rename', 'move') and row['from_path'] and os.path.exists(row['from_path']):
            return False   # l'ancien emplacement est de nouveau occupé
        return True
    except Exception:
        return False


@app.route('/api/journal', methods=['GET'])
@login_required
def api_journal_list():
    """Dernières opérations sur les fichiers (ajout, déplacement, renommage, suppression, conversion, découpe)."""
    if _is_viewer():
        return jsonify({"error": "Accès refusé"}), 403
    try:
        limit = max(1, min(request.args.get('limit', 200, type=int), 500))
        action = (request.args.get('action') or '').strip()
        conn = get_db()
        try:
            if action:
                rows = conn.execute("SELECT * FROM file_journal WHERE user_id = ? AND action = ? ORDER BY ts DESC, id DESC LIMIT ?",
                                    (session['user_id'], action, limit)).fetchall()
            else:
                rows = conn.execute("SELECT * FROM file_journal WHERE user_id = ? ORDER BY ts DESC, id DESC LIMIT ?",
                                    (session['user_id'], limit)).fetchall()
        finally:
            conn.close()
        out = [{
            'id': r['id'], 'ts': r['ts'], 'action': r['action'], 'name': r['name'],
            'from_path': r['from_path'], 'to_path': r['to_path'], 'detail': r['detail'],
            'undone': bool(r['undone']), 'can_undo': _journal_entry_can_undo(r),
        } for r in rows]
        return jsonify({'entries': out, 'retention_days': JOURNAL_RETENTION_DAYS, 'trash_days': _trash_retention_seconds() // 86400})
    except Exception as e:
        app_logger.error(f"[JOURNAL] {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


@app.route('/api/journal/undo', methods=['POST'])
@login_required
def api_journal_undo():
    """Annule un renommage ou un déplacement, ou restaure une suppression encore présente dans la corbeille."""
    if _is_viewer():
        return jsonify({"error": "Accès refusé"}), 403
    try:
        entry_id = (request.get_json(silent=True) or {}).get('id')
        conn = get_db()
        try:
            row = conn.execute("SELECT * FROM file_journal WHERE id = ? AND user_id = ?", (entry_id, session['user_id'])).fetchone()
        finally:
            conn.close()
        if not row:
            return jsonify({"error": "Entrée introuvable"}), 404
        if not _journal_entry_can_undo(row):
            return jsonify({"error": "Cette opération ne peut plus être annulée"}), 409
        dest = row['from_path']
        if not dest or not _is_path_within_sources(dest, session['user_id']):
            return jsonify({"error": "L'emplacement d'origine n'appartient plus à une source configurée"}), 403
        if row['action'] == 'delete' and os.path.exists(dest):
            base, ext = os.path.splitext(dest)
            dest = f"{base}_restauré{ext}"
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        shutil.move(row['to_path'], dest)
        conn = get_db()
        try:
            conn.execute("UPDATE file_journal SET undone = 1 WHERE id = ?", (row['id'],))
            conn.commit()
        finally:
            conn.close()
        journal_log('restore' if row['action'] == 'delete' else 'undo', os.path.basename(dest), row['to_path'], dest)
        invalidate_cache()
        app_logger.info(f"[JOURNAL] ↩ {row['action']} annulé : {os.path.basename(dest)}")
        return jsonify({"success": True, "path": dest})
    except PermissionError:
        return jsonify({"error": "Permission refusée — fichier ouvert dans une autre application ?"}), 403
    except Exception as e:
        app_logger.error(f"[JOURNAL] Annulation impossible : {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


@app.route('/api/thumb/cancel', methods=['POST'])
@login_required
def api_thumb_cancel():
    """Vide la file des miniatures en attente (les rendus déjà commencés vont jusqu'au bout).
    Les fichiers concernés restent sans miniature jusqu'au prochain scan de la bibliothèque."""
    global _thumb_high_pending
    removed = 0
    while True:
        try:
            item = thumb_generation_queue.get_nowait()
        except queue.Empty:
            break
        try:
            if item[0] == 0:
                with _thumb_high_lock:
                    _thumb_high_pending = max(0, _thumb_high_pending - 1)
            task = item[2] if len(item) > 2 else {}
            if task.get('path'):
                _release_thumb_inflight(task['path'])
        finally:
            thumb_generation_queue.task_done()
            removed += 1
    app_logger.info(f"[THUMBS] File vidée par l'utilisateur : {removed} miniature(s) abandonnée(s)")
    return jsonify({"success": True, "removed": removed})


@app.route('/api/thumb/progress', methods=['GET'])
@login_required
def api_thumb_progress():
    pending = thumb_generation_queue.qsize()
    files_without_thumb = 0
    files_with_thumb = 0

    if not _thumb_reconciled_this_run:
        reconcile_thumbnails_with_disk()
        pending = thumb_generation_queue.qsize()

    if os.path.exists(CACHE_FILE):
        try:
            cache = _read_cache_json_safe(attempts=2, delay=0.1) or {}
            for file_entry in cache.get('files', []):
                if file_entry.get('has_thumb'):
                    files_with_thumb += 1
                else:
                    files_without_thumb += 1
        except:
            pass

    total = files_with_thumb + files_without_thumb
    progress = (files_with_thumb / total * 100) if total > 0 else 100

    return jsonify({
        'pending': pending,
        'files_with_thumb': files_with_thumb,
        'files_without_thumb': files_without_thumb,
        'total': total,
        'progress': round(progress, 1),
        'is_generating': pending > 0 or is_generation_running,
        'workers': _thumb_allowed_workers(),
        'paused': _thumb_paused,
        'mode': _thumb_perf_cache['mode'],
        'analysis': dict(_analysis_progress)
    })


