def locate_slicer_by_id(slicer_id):
    entry = _SLICER_CANDIDATES.get(slicer_id)
    if not entry:
        return None
    if sys.platform == 'win32':
        patterns, registry_names = entry['win']
        return _locate_slicer(patterns, registry_names)
    elif sys.platform == 'darwin':
        return _locate_slicer_macos(entry['mac'])
    else:
        for bin_name in entry['linux']:
            path = shutil.which(bin_name)
            if path:
                return path
        return None


def _detect_cura():
    try:
        if sys.platform == 'win32':
            cura_patterns = [
                "Ultimaker Cura*", "UltiMaker Cura*", "Cura*",
                "Elegoo Cura*", "Creality Slicer*", "CrealitySlicer*",
                "Cura LulzBot*", "LulzBot Cura*", "Longer3D Cura*", "Sovol Cura*",
            ]
            for root in _slicer_search_roots():
                for pattern in cura_patterns:
                    for install_dir in glob.glob(os.path.join(root, pattern)):
                        engine_path = os.path.join(install_dir, 'CuraEngine.exe')
                        definitions_dir = os.path.join(install_dir, 'share', 'cura', 'resources', 'definitions')
                        if not os.path.exists(definitions_dir):
                            definitions_dir = os.path.join(install_dir, 'resources', 'definitions')
                        if os.path.exists(engine_path) and os.path.exists(definitions_dir):
                            return {'id': 'cura', 'name': 'Cura', 'path': engine_path,
                                    'definitions_dir': definitions_dir}
        elif sys.platform == 'darwin':
            bundle = _find_app_bundle([
                'UltiMaker Cura.app', 'Ultimaker Cura.app', 'Cura.app',
                'Elegoo Cura.app', 'Creality Slicer.app', 'CrealitySlicer.app',
            ])
            if bundle:
                engine_path = os.path.join(bundle, 'Contents', 'MacOS', 'CuraEngine')
                definitions_dir = os.path.join(bundle, 'Contents', 'Resources', 'resources', 'definitions')
                if os.path.exists(engine_path) and os.path.exists(definitions_dir):
                    return {'id': 'cura', 'name': 'Cura', 'path': engine_path,
                            'definitions_dir': definitions_dir}
        else:
            engine_path = shutil.which('CuraEngine')
            if engine_path:
                return {'id': 'cura', 'name': 'Cura', 'path': engine_path}
    except Exception as e:
        app_logger.info(f"[PreSlice] Détection Cura échouée: {e}")
    return None


def detect_installed_slicers():
    found = []
    for slicer_id, entry in _SLICER_CANDIDATES.items():
        path = locate_slicer_by_id(slicer_id)
        if path:
            found.append({'id': slicer_id, 'name': entry['name'], 'path': path})

    cura = _detect_cura()
    if cura:
        found.append(cura)

    try:
        settings = load_settings()
        custom_path = (settings.get('custom_slicer_path') or '').strip()
        custom_args = (settings.get('custom_slicer_args') or '').strip()
        if custom_path and os.path.exists(custom_path) and custom_args:
            found.append({
                'id': 'custom',
                'name': (settings.get('custom_slicer_name') or 'Slicer personnalisé').strip(),
                'path': custom_path,
                'args_template': custom_args,
                'output_type': (settings.get('custom_slicer_output_type') or 'gcode').strip()
            })
    except Exception as e:
        app_logger.info(f"[PreSlice] Erreur lecture config slicer personnalisé: {e}")

    try:
        preferred = (load_settings().get('preferred_slicer_id') or '').strip()
        if preferred:
            found.sort(key=lambda f: 0 if f['id'] == preferred else 1)
    except Exception:
        pass

    return found

_installed_slicers_cache = {'result': None, 'ts': 0}
def get_cached_installed_slicers(force=False):
    now = time.time()
    if force or _installed_slicers_cache['result'] is None or (now - _installed_slicers_cache['ts']) > 300:
        _installed_slicers_cache['result'] = detect_installed_slicers()
        _installed_slicers_cache['ts'] = now
    return _installed_slicers_cache['result']

def _parse_duration_to_seconds(raw):
    if raw is None:
        return None
    if isinstance(raw, (int, float)):
        return int(raw)
    raw = str(raw).strip()
    if raw.isdigit():
        return int(raw)
    total = 0
    matches = re.findall(r'(\d+)\s*([dhms])', raw.lower())
    for value, unit in matches:
        value = int(value)
        total += {'d': 86400, 'h': 3600, 'm': 60, 's': 1}[unit] * value
    return total if total > 0 else None

def _seconds_to_result(weight_g, seconds):
    result = {}
    if weight_g is not None:
        try:
            result['weight_g'] = round(float(weight_g), 1)
        except (TypeError, ValueError):
            pass
    if seconds is not None:
        try:
            seconds = int(seconds)
            hours, minutes = seconds // 3600, (seconds % 3600) // 60
            result['time_seconds'] = seconds
            result['time_formatted'] = f"{hours}h {minutes}min" if hours > 0 else f"{minutes}min"
        except (TypeError, ValueError):
            pass
    return result or None

def _extract_gcode_from_gcode3mf(gcode3mf_path):
    try:
        with zipfile.ZipFile(gcode3mf_path, 'r') as zf:
            gcode_entries = sorted([n for n in zf.namelist() if n.lower().endswith('.gcode')])
            if not gcode_entries:
                return None
            plate1 = [n for n in gcode_entries if 'plate_1' in n.lower()]
            target = plate1[0] if plate1 else gcode_entries[0]
            return zf.read(target).decode('utf-8', errors='ignore')
    except Exception as e:
        app_logger.info(f"[PreSlice] Erreur lecture .gcode.3mf: {e}")
        return None

_WEIGHT_PATTERNS = [
    r'(?:total\s+)?filament used\s*\[g\]\s*[:=]\s*([\d.]+)',
    r'total filament weight\s*\[g\]\s*[:=]\s*([\d.]+)',
    r'total[_ ]filament[_ ]used\s*[:=]\s*([\d.]+)\s*g',
    r'filament_used_g\s*[:=]\s*([\d.]+)',
]
_TIME_PATTERNS = [
    r'total estimated time\s*[:=]\s*([^\n\r;]+)',
    r'estimated printing time[^=:]*[:=]\s*([^\n\r;]+)',
    r'model printing time\s*[:=]\s*([^\n\r;]+)',
    r'estimated_time\s*[:=]\s*([^\n\r;]+)',
]
_CURA_TIME_PATTERN = r';TIME:\s*(\d+)'
_CURA_FILAMENT_LENGTH_PATTERN = r';Filament used:\s*([\d.]+)m'
DEFAULT_FILAMENT_DIAMETER_MM = 1.75
DEFAULT_FILAMENT_DENSITY_G_CM3 = 1.24

def _filament_length_m_to_weight_g(length_m, diameter_mm=DEFAULT_FILAMENT_DIAMETER_MM, density=DEFAULT_FILAMENT_DENSITY_G_CM3):
    radius_cm = (diameter_mm / 10) / 2
    volume_cm3 = 3.14159265 * (radius_cm ** 2) * (length_m * 100)
    return volume_cm3 * density

def _extract_weight_time_from_gcode_text(blob, is_cura=False):
    weight_g = None
    seconds = None

    if is_cura:
        m = re.search(_CURA_TIME_PATTERN, blob)
        if m:
            seconds = int(m.group(1))
        m = re.search(_CURA_FILAMENT_LENGTH_PATTERN, blob)
        if m:
            try:
                weight_g = _filament_length_m_to_weight_g(float(m.group(1)))
            except ValueError:
                pass
        result = _seconds_to_result(weight_g, seconds)
        if result:
            result['weight_approximate'] = True
        return result

    for pattern in _WEIGHT_PATTERNS:
        m = re.search(pattern, blob, re.IGNORECASE)
        if m:
            try:
                weight_g = float(m.group(1))
                break
            except ValueError:
                continue

    for pattern in _TIME_PATTERNS:
        m = re.search(pattern, blob, re.IGNORECASE)
        if m:
            seconds = _parse_duration_to_seconds(m.group(1))
            if seconds:
                break

    return _seconds_to_result(weight_g, seconds)

def parse_bambu_orca_gcode3mf(gcode3mf_path):
    gcode_text = _extract_gcode_from_gcode3mf(gcode3mf_path)
    if not gcode_text:
        return None
    blob = gcode_text[:6000] + '\n' + gcode_text[-6000:]
    return _extract_weight_time_from_gcode_text(blob)

def parse_slic3r_derived_gcode(gcode_path):
    if not os.path.exists(gcode_path):
        return None
    try:
        file_size = os.path.getsize(gcode_path)
        with open(gcode_path, 'rb') as f:
            f.seek(max(0, file_size - 8192))
            tail = f.read().decode('utf-8', errors='ignore')
        with open(gcode_path, 'r', encoding='utf-8', errors='ignore') as f:
            head = f.read(4096)
        blob = head + '\n' + tail
        return _extract_weight_time_from_gcode_text(blob)
    except Exception as e:
        app_logger.info(f"[PreSlice] Erreur parsing gcode: {e}")
        return None

def parse_cura_gcode(gcode_path):
    if not os.path.exists(gcode_path):
        return None
    try:
        with open(gcode_path, 'r', encoding='utf-8', errors='ignore') as f:
            head = f.read(4096)
        return _extract_weight_time_from_gcode_text(head, is_cura=True)
    except Exception as e:
        app_logger.info(f"[PreSlice] Erreur parsing gcode Cura: {e}")
        return None

def parse_generic_output(output_path):
    if not os.path.exists(output_path):
        return None
    if output_path.lower().endswith('.3mf'):
        return parse_bambu_orca_gcode3mf(output_path)
    result = parse_cura_gcode(output_path)
    if result:
        return result
    return parse_slic3r_derived_gcode(output_path)

def _json_profile_type(path):
    try:
        with open(path, 'r', encoding='utf-8-sig') as f:
            return str((json.load(f) or {}).get('type') or '').strip().lower()
    except Exception:
        return ''


def run_silent_slice(stl_path, slicer, timeout=150, override=None, diag=None):
    slug = hashlib.md5(f"{stl_path}|{time.time()}".encode()).hexdigest()[:12]
    out_dir = os.path.join(get_slice_temp_dir(), slug)
    os.makedirs(out_dir, exist_ok=True)

    try:
        settings = load_settings()
        if slicer['id'] in ('orcaslicer', 'bambustudio', 'qidistudio', 'elegooslicer', 'anycubicslicernext'):
            out_3mf = os.path.join(out_dir, 'preslice.gcode.3mf')
            cmd = [slicer['path'], '--slice', '1', '--allow-newer-file', '--mstpp', str(max(30, timeout - 20))]

            load_settings_str = (settings.get('slicer_profile_settings') or '').strip()
            load_filament_str = (settings.get('slicer_profile_filament') or '').strip()
            if override is not None:
                ov_settings = list(override.get('settings') or [])
                ov_filaments = list(override.get('filaments') or [])
                try:
                    _printer_paths = {p.get('source_path') for p in load_slicer_profiles() if p.get('profile_type') == 'printer'}
                except Exception:
                    _printer_paths = set()
                has_machine = any((x in _printer_paths) or _json_profile_type(x) == 'machine' for x in ov_settings)
                if not has_machine:
                    global_machine = [x.strip() for x in load_settings_str.split(';')
                                      if x.strip() and x.strip() not in ov_settings and _json_profile_type(x.strip()) == 'machine']
                    ov_settings = global_machine + ov_settings
                if not ov_filaments:
                    ov_filaments = [x.strip() for x in load_filament_str.split(';') if x.strip()]
                load_settings_str = ';'.join(ov_settings)
                load_filament_str = ';'.join(ov_filaments)
            if load_settings_str:
                cmd += ['--load-settings', load_settings_str]
            if load_filament_str:
                cmd += ['--load-filaments', load_filament_str]

            cmd += ['--export-3mf', out_3mf, stl_path]
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, **_popen_kwargs_silent())
            tail = ((result.stderr or '').strip() or (result.stdout or '').strip())[-700:]
            if diag is not None:
                diag['returncode'] = result.returncode
                diag['output'] = tail
            if not os.path.exists(out_3mf):
                app_logger.info(f"[PreSlice] Pas de sortie générée par {slicer['name']} (code {result.returncode}) - "
                                f"settings={load_settings_str!r} filaments={load_filament_str!r} - sortie: {tail}")
                parsed = None
            else:
                parsed = parse_bambu_orca_gcode3mf(out_3mf)
                if parsed is None and diag is not None and not diag.get('output'):
                    diag['output'] = "Fichier généré mais temps/poids illisibles"
        elif slicer['id'] in ('prusaslicer', 'superslicer'):
            gcode_path = os.path.join(out_dir, 'preslice.gcode')
            cmd = [slicer['path'], '--export-gcode', '--output', gcode_path]

            profile_key = 'slicer_profile_prusa_ini' if slicer['id'] == 'prusaslicer' else 'slicer_profile_super_ini'
            ini_str = (settings.get(profile_key) or '').strip()
            if override is not None:
                ini_str = ';'.join((override.get('settings') or []) + (override.get('filaments') or []))
            if ini_str:
                for ini_path in ini_str.split(';'):
                    ini_path = ini_path.strip()
                    if ini_path:
                        cmd += ['--load', ini_path]

            cmd += [stl_path]
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, **_popen_kwargs_silent())
            if diag is not None:
                diag['returncode'] = result.returncode
                diag['output'] = ((result.stderr or '').strip() or (result.stdout or '').strip())[-700:]
            if not os.path.exists(gcode_path):
                if not ini_str:
                    app_logger.info(f"[PreSlice] {slicer['name']} n'a rien généré (aucun profil .ini configuré) - "
                                     f"renseigne '{profile_key}' dans app_settings.json. stderr: {(result.stderr or '')[:300]}")
                else:
                    app_logger.info(f"[PreSlice] Pas de sortie générée par {slicer['name']} - stderr: {(result.stderr or '')[:300]}")
                parsed = None
            else:
                parsed = parse_slic3r_derived_gcode(gcode_path)

        elif slicer['id'] == 'cura':
            gcode_path = os.path.join(out_dir, 'preslice.gcode')
            definitions_dir = slicer.get('definitions_dir')
            definition_file = (settings.get('cura_definition_file') or 'fdmprinter.def.json').strip()
            cmd = [slicer['path'], 'slice']
            if definitions_dir:
                cmd += ['-j', os.path.join(definitions_dir, definition_file)]
            cmd += ['-l', stl_path, '-o', gcode_path]
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, **_popen_kwargs_silent())
            if not os.path.exists(gcode_path):
                app_logger.info(f"[PreSlice] Pas de sortie générée par CuraEngine - stderr: {(result.stderr or '')[:300]}")
                parsed = None
            else:
                parsed = parse_cura_gcode(gcode_path)

        elif slicer['id'] == 'custom':
            output_type = slicer.get('output_type', 'gcode')
            out_name = 'preslice.gcode.3mf' if output_type == 'gcode3mf' else 'preslice.gcode'
            out_path = os.path.join(out_dir, out_name)
            try:
                args_str = slicer['args_template'].replace('{input}', stl_path).replace('{output}', out_path)
                cmd = [slicer['path']] + shlex.split(args_str, posix=(sys.platform != 'win32'))
            except Exception as e:
                app_logger.warning(f"[PreSlice] Template de commande invalide pour le slicer personnalisé: {e}")
                parsed = None
            else:
                result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, **_popen_kwargs_silent())
                if not os.path.exists(out_path):
                    app_logger.info(f"[PreSlice] Pas de sortie générée par {slicer['name']} - stderr: {(result.stderr or '')[:300]}")
                    parsed = None
                else:
                    parsed = parse_generic_output(out_path)
        else:
            parsed = None

        if parsed:
            parsed['slicer_name'] = slicer['name']
        return parsed
    except subprocess.TimeoutExpired:
        app_logger.warning(f"[PreSlice] Timeout ({timeout}s) pour {os.path.basename(stl_path)}")
        return None
    except Exception as e:
        app_logger.warning(f"[PreSlice] Erreur slicing silencieux {os.path.basename(stl_path)}: {e}")
        return None
    finally:
        shutil.rmtree(out_dir, ignore_errors=True)


slice_estimate_queue = queue.Queue()
slice_estimate_results = collections.OrderedDict()
slice_estimate_lock = threading.Lock()
NUM_SLICE_WORKERS = 1

SLICE_ESTIMATE_CACHE_MAX = 500

def _slice_cache_set(file_path, value):
    slice_estimate_results[file_path] = value
    slice_estimate_results.move_to_end(file_path)
    while len(slice_estimate_results) > SLICE_ESTIMATE_CACHE_MAX:
        slice_estimate_results.popitem(last=False)

def process_slice_estimate_queue():
    def slice_worker(worker_id):
        _lower_thread_priority()
        app_logger.info(f"[PreSlice] Worker #{worker_id} démarré")
        while True:
            try:
                task = slice_estimate_queue.get(timeout=1)
            except queue.Empty:
                time.sleep(0.5)
                continue
            file_path = task.get('path')
            cache_key = task.get('key') or file_path
            profile_id = task.get('profile_id')
            tmp_stl = None
            try:
                if is_virtual_archive_path(file_path):
                    archive_path, internal_path = split_virtual_archive_path(file_path)
                    raw_bytes = read_archive_entry_bytes(archive_path, internal_path)
                    tmp_fd, tmp_stl = tempfile.mkstemp(suffix=os.path.splitext(internal_path)[1])
                    with os.fdopen(tmp_fd, 'wb') as f:
                        f.write(raw_bytes)
                    stl_for_slicer = tmp_stl
                else:
                    stl_for_slicer = file_path

                # Le tranchage silencieux n'est garanti que pour STL/3MF/OBJ : STEP, PLY et AMF passent par un STL temporaire
                stl_for_slicer = _prepare_model_for_slicer(stl_for_slicer, '', '', force=True) or stl_for_slicer

                # Taille demandée ≠ 100 % : le slicer tranche une copie mise à l'échelle (STL temporaire)
                scale_pct = _clean_scale_pct(task.get('scale'))
                if scale_pct != 100:
                    src_for_scale = file_path if not is_virtual_archive_path(file_path) else stl_for_slicer
                    if str(src_for_scale).lower().endswith('.3mf'):
                        scaled = load_3mf_mesh(src_for_scale)
                    else:
                        scaled = load_model_mesh(src_for_scale)
                    if isinstance(scaled, trimesh.Scene):
                        scaled = trimesh.util.concatenate([g for g in scaled.geometry.values() if hasattr(g, 'faces')])
                    scaled = scaled.copy()
                    scaled.apply_scale(scale_pct / 100.0)
                    scaled.apply_translation(-scaled.bounds.mean(axis=0) + [0, 0, 0])
                    sfd, scaled_path = tempfile.mkstemp(suffix='.stl')
                    os.close(sfd)
                    scaled.export(scaled_path)
                    if tmp_stl and os.path.exists(tmp_stl) and tmp_stl != scaled_path:
                        try:
                            os.remove(tmp_stl)
                        except Exception:
                            pass
                    tmp_stl = scaled_path
                    stl_for_slicer = scaled_path

                slicers = get_cached_installed_slicers()
                if not slicers or not any(s.get('preslice_supported', True) for s in slicers):
                    with slice_estimate_lock:
                        _slice_cache_set(cache_key, {'status': 'unavailable', 'reason': 'no_slicer'})
                    continue

                override = None
                if profile_id:
                    prof = next((p for p in load_slicer_profiles() if p.get('id') == profile_id), None)
                    fam = ((prof or {}).get('slicer') or '').strip().lower()
                    if prof and not fam:
                        wanted = (_SLICER_LOAD_INI_FAMILIES if str(prof.get('source_path') or '').lower().endswith('.ini')
                                  else ('orcaslicer', 'bambustudio', 'qidistudio', 'elegooslicer', 'anycubicslicernext'))
                        cand = next((s for s in slicers if s.get('preslice_supported', True) and s.get('id') in wanted), None)
                        fam = cand['id'] if cand else ''
                    slicer = next((s for s in slicers if s.get('preslice_supported', True) and s.get('id') == fam), None)
                    if not prof or slicer is None or fam not in (_SLICER_LOAD_SETTINGS_FAMILIES + _SLICER_LOAD_INI_FAMILIES):
                        with slice_estimate_lock:
                            _slice_cache_set(cache_key, {'status': 'unavailable', 'reason': 'profile_slicer_unavailable'})
                        continue
                    s_paths, f_paths, _ids = _resolve_slicer_profile_paths(
                        fam, task.get('printer_id'), task.get('material_type'), profile_id)
                    if not s_paths:
                        with slice_estimate_lock:
                            _slice_cache_set(cache_key, {'status': 'unavailable', 'reason': 'profile_unreadable'})
                        continue
                    override = {'settings': s_paths, 'filaments': f_paths}
                else:
                    slicer = next(s for s in slicers if s.get('preslice_supported', True))
                diag = {}
                data = run_silent_slice(stl_for_slicer, slicer, override=override, diag=diag)

                with slice_estimate_lock:
                    if data:
                        _slice_cache_set(cache_key, {'status': 'done', 'data': data})
                    else:
                        _slice_cache_set(cache_key, {'status': 'error', 'reason': 'slice_failed',
                                                     'detail': (diag.get('output') or '')[-500:],
                                                     'returncode': diag.get('returncode')})
            except Exception as e:
                app_logger.warning(f"[PreSlice] Erreur worker: {e}")
                with slice_estimate_lock:
                    _slice_cache_set(cache_key, {'status': 'error', 'reason': str(e)})
            finally:
                if tmp_stl and os.path.exists(tmp_stl):
                    try:
                        os.remove(tmp_stl)
                    except Exception:
                        pass
                slice_estimate_queue.task_done()

    for i in range(NUM_SLICE_WORKERS):
        threading.Thread(target=slice_worker, args=(i,), daemon=True).start()
    app_logger.info(f"[PreSlice] File d'attente de pre-slicing active ({NUM_SLICE_WORKERS} worker)")

def detect_platform_from_path(file_path):
    path_lower = (file_path or '').lower().replace('\\', '/')
    if 'thingiverse' in path_lower:
        return 'Thingiverse'
    if 'printables' in path_lower:
        return 'Printables'
    if 'makerworld' in path_lower:
        return 'MakerWorld'
    if 'nexprint' in path_lower:
        return 'Nexprint'
    return ''

def find_slicer_by_name(slicer_name):
    if not slicer_name or slicer_name == 'system_default':
        return None

    slicer_id = next((k for k, v in SLICER_ID_TO_DEFAULT_VALUE.items() if v == slicer_name), None)
    if not slicer_id:
        return None
    if slicer_id == 'cura':
        cura = _detect_cura()
        return cura['path'] if cura else None
    return locate_slicer_by_id(slicer_id)

def _clean_scale_pct(value):
    try:
        v = float(value)
    except (TypeError, ValueError):
        return 100
    return int(round(min(1000.0, max(10.0, v))))


def _slice_estimate_key(file_path, profile_id=None, printer_id=None, material_type=None, scale=100):
    profile_id = (str(profile_id).strip() if profile_id else '')
    scale = _clean_scale_pct(scale)
    if not profile_id and scale == 100:
        return file_path
    return f"{file_path}||{profile_id}|{printer_id or ''}|{(material_type or '').strip().lower()}" + (f"|s{scale}" if scale != 100 else '')


@app.route('/api/slicer/pre-slice-estimate', methods=['POST'])
@login_required
def api_request_slice_estimate():
    data = request.json or {}
    file_path = (data.get('path') or '').strip()
    if not file_path:
        return jsonify({"error": "Chemin requis"}), 400
    profile_id = (str(data.get('profile_id') or '')).strip() or None
    printer_id = data.get('printer_id') or None
    material_type = (data.get('material_type') or '').strip() or None
    scale_pct = _clean_scale_pct(data.get('scale'))
    key = _slice_estimate_key(file_path, profile_id, printer_id, material_type, scale_pct)
    _sync_slicer_profiles(session['user_id'])   

    with slice_estimate_lock:
        existing = slice_estimate_results.get(key)
    if existing and existing.get('status') in ('done', 'error', 'unavailable'):
        return jsonify(existing), 200

    if not is_virtual_archive_path(file_path) and not os.path.exists(file_path):
        return jsonify({"error": "Fichier non trouvé"}), 404
    if is_virtual_archive_path(file_path):
        archive_path, _ = split_virtual_archive_path(file_path)
        if not os.path.exists(archive_path):
            return jsonify({"error": "Archive non trouvée"}), 404

    with slice_estimate_lock:
        if key not in slice_estimate_results or slice_estimate_results[key].get('status') == 'error':
            _slice_cache_set(key, {'status': 'pending'})
            slice_estimate_queue.put({'path': file_path, 'key': key, 'profile_id': profile_id,
                                      'printer_id': printer_id, 'material_type': material_type, 'scale': scale_pct})
        result = slice_estimate_results[key]

    return jsonify(result), 202

def _get_cached_slice_estimate_seconds(file_path):
    with slice_estimate_lock:
        entry = slice_estimate_results.get(file_path)
    if entry and entry.get('status') == 'done':
        return entry.get('data', {}).get('time_seconds')
    return None

@app.route('/api/slicer/pre-slice-estimate', methods=['GET'])
@login_required
def api_get_slice_estimate():
    file_path = (request.args.get('path') or '').strip()
    if not file_path:
        return jsonify({"error": "Chemin requis"}), 400
    key = _slice_estimate_key(file_path, request.args.get('profile_id'), request.args.get('printer_id'),
                              request.args.get('material_type'), request.args.get('scale'))
    with slice_estimate_lock:
        result = slice_estimate_results.get(key, {'status': 'unknown'})
    return jsonify(result), 200

_SLICER_FAMILY_BY_FILENAME = {
    'orca-slicer.exe': 'orcaslicer',
    'orcaslicer.exe': 'orcaslicer',
    'bambu-studio.exe': 'bambustudio',
    'bambustudio.exe': 'bambustudio',
    'qidi-studio.exe': 'qidistudio',
    'qidistudio.exe': 'qidistudio',
    'qidi-studio': 'qidistudio',
    'prusa-slicer.exe': 'prusaslicer',
    'prusa-slicer-console.exe': 'prusaslicer',
    'superslicer.exe': 'superslicer',
    'superslicer_console.exe': 'superslicer',
    'elegooslicer.exe': 'elegooslicer',
    'anycubicslicernext.exe': 'anycubicslicernext',


    'creality print.exe': 'creality_print',
    'crealityprint.exe': 'creality_print',
}


def _resolve_slicer_family(slicer_path, slicer_name):
    basename = os.path.basename(slicer_path).lower() if slicer_path else ''
    return (_SLICER_FAMILY_BY_FILENAME.get(basename)
            or _SLICER_FAMILY_BY_FILENAME.get((slicer_name or '').lower()))


_SLICER_LOAD_SETTINGS_FAMILIES = ('orcaslicer', 'bambustudio', 'qidistudio', 'elegooslicer', 'anycubicslicernext', 'creality_print')
_SLICER_LOAD_INI_FAMILIES = ('prusaslicer', 'superslicer')


def _resolve_slicer_profile_paths(slicer_family, printer_id, material_type=None, process_profile_id=None):
    if not slicer_family:
        return [], [], []

    printer_id_int = None
    if printer_id:
        try:
            printer_id_int = int(printer_id)
        except (TypeError, ValueError):
            printer_id_int = None
    process_profile_id = (str(process_profile_id).strip() if process_profile_id else '') or None
    if printer_id_int is None and not process_profile_id:
        return [], [], []

    profiles = load_slicer_profiles()
    settings_paths, filament_paths, matched_ids = [], [], []

    if printer_id_int is not None:
        for p in profiles:
            if p.get('printer_id') != printer_id_int:
                continue
            if not p.get('source_path') or not os.path.exists(p['source_path']):
                continue
            p_slicer = (p.get('slicer') or '').strip().lower()
            if p_slicer and p_slicer != slicer_family:
                continue

            ptype = p.get('profile_type')
            if ptype == 'filament':
                if material_type and (p.get('material_type') or '').strip().lower() != material_type.strip().lower():
                    continue
                filament_paths.append(p['source_path'])
                matched_ids.append(p['id'])
            elif ptype in ('process', 'printer'):
                settings_paths.append(p['source_path'])
                matched_ids.append(p['id'])

        confirmed_settings = [p['source_path'] for p in profiles
                               if p.get('printer_id') == printer_id_int and p.get('printer_match_confirmed')
                               and p.get('profile_type') in ('process', 'printer')
                               and p.get('source_path') and os.path.exists(p['source_path'])
                               and (not (p.get('slicer') or '').strip() or (p.get('slicer') or '').strip().lower() == slicer_family)]
        if confirmed_settings:
            settings_paths = confirmed_settings

    if process_profile_id:
        chosen = next((p for p in profiles
                       if p.get('id') == process_profile_id and p.get('profile_type') == 'process'
                       and p.get('source_path') and os.path.exists(p['source_path'])
                       and (not (p.get('slicer') or '').strip() or (p.get('slicer') or '').strip().lower() == slicer_family)), None)
        if chosen:
            process_paths = {p['source_path'] for p in profiles if p.get('profile_type') == 'process' and p.get('source_path')}
            process_ids = {p['id'] for p in profiles if p.get('profile_type') == 'process'}
            settings_paths = [sp for sp in settings_paths if sp not in process_paths] + [chosen['source_path']]
            matched_ids = [i for i in matched_ids if i not in process_ids] + [chosen['id']]
        else:
            app_logger.warning(f"[Slicer] Profil de réglages {process_profile_id} introuvable, illisible ou incompatible avec {slicer_family} : ignoré")

    return settings_paths, filament_paths, matched_ids


@app.route('/api/slicer/process-profiles', methods=['GET'])
@login_required
def api_slicer_process_profiles():
    synced = _sync_slicer_profiles(session['user_id'])
    settings = load_settings() or {}
    slicer_name = settings.get('default_slicer', 'system_default')
    slicer_path = find_slicer_by_name(slicer_name)
    family = _resolve_slicer_family(slicer_path, slicer_name) if slicer_path else None
    all_slicers = str(request.args.get('all_slicers') or '') in ('1', 'true')
    printer_id = _safe_int(request.args.get('printer_id'))
    out = []
    for p in load_slicer_profiles():
        if p.get('profile_type') != 'process':
            continue
        if not p.get('source_path') or not os.path.exists(p['source_path']):
            continue  
        p_slicer = (p.get('slicer') or '').strip().lower()
        if not all_slicers and family and p_slicer and p_slicer != family:
            continue
        pid = p.get('printer_id')
        if printer_id is not None and pid not in (None, printer_id):
            continue
        out.append({
            'id': p['id'], 'name': p.get('name') or p.get('source_filename') or 'Profil', 'slicer': p_slicer,
            'layer_height': p.get('layer_height'), 'infill_density': p.get('infill_density'),
            'print_speed': p.get('print_speed'), 'wall_count': p.get('wall_count'),
            'supports_enabled': p.get('supports_enabled'),
            'printer_matched': printer_id is not None and pid == printer_id,
        })
    out.sort(key=lambda x: (not x['printer_matched'], x['name'].lower()))
    return jsonify({'profiles': out, 'slicer_family': family, 'synced': synced}), 200


@app.route('/api/slicer/send', methods=['POST'])
@login_required
def api_send_to_slicer():
    data = request.json
    file_path = data.get('file_path', '')
    is_smb_file = file_path.startswith('//') or file_path.startswith('\\\\')
    # Édition serveur : pas de slicer sur la machine, le fichier est ouvert dans le slicer du PC de l'utilisateur
    pc_mode = IS_SERVER_EDITION
    if not file_path or (not os.path.exists(file_path) and not (pc_mode and is_smb_file)):
        return jsonify({"error": "Fichier non trouvé"}), 404
    if not _is_path_within_sources(file_path, session['user_id']):
        app_logger.warning(f"[SECURITY] Tentative d'ouverture slicer hors sources: {file_path}")
        return jsonify({"error": "Ce fichier n'appartient à aucune source configurée"}), 403

    if not data.get('ignore_stock'):
        _alerts = _check_restock_for_files([file_path], session['user_id'])
        if _alerts:
            return jsonify({"stock_insufficient": True, "alert": _alerts[0],
                            "message": "Bobine insuffisante pour ce fichier."}), 409

    if not data.get('force'):
        try:
            conn_check = get_db()
            recent = conn_check.execute(
                "SELECT sent_at FROM print_history WHERE user_id=? AND file_path=? "
                "AND sent_at > datetime('now', '-2 minutes') ORDER BY sent_at DESC LIMIT 1",
                (session['user_id'], file_path.replace('\\', '/'))
            ).fetchone()
            conn_check.close()
            if recent:
                seconds_ago = None
                try:
                    sent_dt = datetime.datetime.fromisoformat(recent['sent_at'])
                    seconds_ago = max(0, int((datetime.datetime.now() - sent_dt).total_seconds()))
                except Exception:
                    pass
                return jsonify({
                    "duplicate_send": True,
                    "seconds_ago": seconds_ago,
                    "message": "Ce fichier a déjà été envoyé au slicer il y a moins de 2 minutes — probablement depuis un autre appareil connecté à Stellio. Confirmez pour l'envoyer quand même."
                }), 409
        except Exception as e:
            app_logger.debug(f"[Slicer] Vérification de doublon ignorée: {e}")

    try:
        settings = load_settings()
        slicer_name = settings.get('default_slicer', 'system_default')
        slicer_path = find_slicer_by_name(slicer_name)
        detected_slicer = os.path.basename(slicer_path).replace('.exe','') if slicer_path else 'Défaut système'
        if pc_mode:
            detected_slicer = (slicer_name or '').replace('.exe', '') if slicer_name and slicer_name != 'system_default' else 'Slicer du PC'

        orientation_key = data.get('orientation') or 'default'
        if pc_mode and is_smb_file:
            reoriented_path = converted_path = None
        else:
            reoriented_path = _export_reoriented_mesh(file_path, orientation_key)
            converted_path = None if (reoriented_path or pc_mode) else _prepare_model_for_slicer(file_path, slicer_name, slicer_path)
        path_to_open = reoriented_path or converted_path or file_path

        pc_open = None
        if pc_mode:
            smb_kw = None
            if is_smb_file:
                smb_kw = _smb_kwargs_for_path(session['user_id'], file_path)
                if smb_kw is None:
                    return jsonify({"error": "Source réseau introuvable pour ce fichier"}), 404
                try:
                    smbclient.stat(file_path.replace('\\', '/'), connection_timeout=8, **smb_kw)
                except Exception as smb_err:
                    app_logger.warning(f"[Slicer] SMB inaccessible: {smb_err}")
                    return jsonify({"error": "Source réseau injoignable"}), 503
            _cleanup_slicer_fetch_links()
            ftoken = secrets.token_urlsafe(24)
            with _share_lock:
                _slicer_fetch_links[ftoken] = {
                    'path': path_to_open, 'smb': bool(smb_kw is not None), 'smb_kwargs': smb_kw or {},
                    'name': os.path.basename(file_path.replace('\\', '/')) if path_to_open == file_path
                            else os.path.basename(path_to_open),
                    'created': time.time(),
                }
            fname = _slicer_fetch_links[ftoken]['name']
            pc_open = {
                "url": f"{request.host_url.rstrip('/')}/api/slicer-fetch/{ftoken}/{urllib.parse.quote(fname)}",
                "slicer": slicer_name or 'system_default',
                "name": fname,
            }


        applied_profile_ids = []
        printer_id = data.get('printer_id')
        if pc_mode:
            pass
        elif slicer_path:
            slicer_family = _resolve_slicer_family(slicer_path, slicer_name)
            printer_id = data.get('printer_id')
            material_type = data.get('material_type')
            process_profile_id = (data.get('process_profile_id') or '').strip() or None
            cmd = [slicer_path]

            if slicer_family and (printer_id or process_profile_id):
                settings_paths, filament_paths, matched_ids = _resolve_slicer_profile_paths(
                    slicer_family, printer_id, material_type, process_profile_id
                )
                applied_profile_ids = matched_ids
                if process_profile_id and process_profile_id in matched_ids and not data.get('slicer_profile_id'):
                    data['slicer_profile_id'] = process_profile_id   # journalisé dans l'historique d'impression
                if slicer_family in _SLICER_LOAD_SETTINGS_FAMILIES:
                    if settings_paths:
                        cmd += ['--load-settings', ';'.join(settings_paths)]
                    if filament_paths:
                        cmd += ['--load-filaments', ';'.join(filament_paths)]
                elif slicer_family in _SLICER_LOAD_INI_FAMILIES:
                    for ini_path in (settings_paths + filament_paths):
                        cmd += ['--load', ini_path]
                if not settings_paths and not filament_paths:
                    app_logger.info(f"[Slicer] Aucun profil importé rattaché à l'imprimante {printer_id} pour {slicer_family}, ouverture sans --load-settings")

            cmd.append(path_to_open)
            subprocess.Popen(cmd)
        else:
            try:
                if sys.platform == 'win32':
                    os.startfile(path_to_open)
                elif sys.platform == 'darwin':
                    result = subprocess.run(['open', path_to_open], check=False, capture_output=True, text=True)
                    if result.returncode != 0:
                        raise RuntimeError(result.stderr.strip() or f"'open' a échoué (code {result.returncode})")
                else:
                    result = subprocess.run(['xdg-open', path_to_open], check=False, capture_output=True, text=True)
                    if result.returncode != 0:
                        raise RuntimeError(result.stderr.strip() or f"'xdg-open' a échoué (code {result.returncode})")
            except Exception as open_err:
                app_logger.warning(f"[Slicer] Aucun slicer configuré et ouverture par défaut du système impossible : {open_err}")
                return jsonify({
                    "error": "Aucun slicer n'est renseigné (et aucune application par défaut n'est associée à ce type de fichier sur votre système). Configurez votre slicer dans Paramètres > Slicer."
                }), 400

        try:
            conn = get_db()
            norm = file_path.replace('\\', '/')

            assignment_row = conn.execute(
                "SELECT source_type, source_id FROM filament_assignments WHERE file_path=? AND user_id=?",
                (norm, session['user_id'])
            ).fetchone()

            spool_id_logged, weight_used_logged = None, None
            if assignment_row and data.get('consume_spool'):
                source_type, source_id = assignment_row
                required_g, _ = _get_required_weight_for_file(norm)
                if required_g:
                    if _consume_filament_slot(source_type, source_id, required_g, session['user_id']):
                        weight_used_logged = required_g
                        if source_type == 'spoolman':
                            try:
                                spool_id_logged = int(source_id)
                            except (TypeError, ValueError):
                                spool_id_logged = None

            material_cost, elec_cost, total_cost, _weight_for_cost = _compute_estimated_cost(norm, weight_g_hint=weight_used_logged)
            estimated_seconds_logged = _get_cached_slice_estimate_seconds(norm)

            fil = _filament_info_for_file(conn, session['user_id'], norm)
            cur = conn.execute(
                "INSERT INTO print_history (user_id, file_path, file_name, file_size, file_ext, slicer, source_platform, spool_id, spool_weight_used_g, slicer_profile_id, slicer_profile_name, material_cost, elec_cost, total_cost, printer_id, estimated_seconds, filament_material, filament_label, spool_source_type, spool_source_id, assignment_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (session['user_id'], norm, os.path.basename(file_path),
                 os.path.getsize(file_path) if os.path.exists(file_path) else 0,
                 os.path.splitext(file_path)[1].lower(), detected_slicer,
                 detect_platform_from_path(norm), spool_id_logged, weight_used_logged,
                 data.get('slicer_profile_id') or (applied_profile_ids[0] if applied_profile_ids else ''), data.get('slicer_profile_name') or '',
                 material_cost, elec_cost, total_cost, printer_id, estimated_seconds_logged, fil['material'], fil['label'],
                 fil['source_type'], fil['source_id'], fil['snapshot'])
            )
            history_id = cur.lastrowid
            conn.commit()
            conn.close()
        except Exception as log_err:
            app_logger.warning(f"[PrintHistory] Log échoué: {log_err}")
            history_id = None

        return jsonify({"message": f"Envoyé via {detected_slicer}", "history_id": history_id, "pc_open": pc_open,
                         "stock_warning": None if data.get('ignore_stock') else (_check_restock_for_files([file_path], session['user_id']) or [None])[0]}), 200

    except Exception as e:
        app_logger.error(f"[API] Erreur non gérée: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500

@app.route('/api/slicer/send-batch', methods=['POST'])
@login_required
def api_slicer_send_batch():
    try:
        data = request.json
        file_paths = data.get('files', [])
        if not file_paths:
            return jsonify({"error": "Aucun fichier sélectionné"}), 400
        for fp in file_paths:
            if not _is_path_within_sources(fp, session['user_id']):
                app_logger.warning(f"[SECURITY] Tentative d'ouverture slicer (batch) hors sources: {fp}")
                return jsonify({"error": "Un ou plusieurs fichiers n'appartiennent à aucune source configurée"}), 403

        if not data.get('ignore_stock'):
            _alerts = _check_restock_for_files(file_paths, session['user_id'])
            if _alerts:
                return jsonify({"stock_insufficient": True, "alerts": _alerts, "alert": _alerts[0],
                                "message": "Bobine insuffisante pour un ou plusieurs fichiers."}), 409

        if sys.platform == 'win32':
            file_paths = [p.replace('/', '\\') for p in file_paths]


        settings = load_settings()
        slicer_name = settings.get('default_slicer', 'system_default')
        slicer_path = find_slicer_by_name(slicer_name)

        if not slicer_path:
            installed = get_cached_installed_slicers()
            if installed:
                slicer_path = installed[0]['path']

        if not slicer_path:
            return jsonify({
                "error": "Aucun slicer trouvé. Installez OrcaSlicer, BambuStudio, PrusaSlicer ou Cura."
            }), 404


        applied_profile_ids = []
        cmd = [slicer_path]
        slicer_family = _resolve_slicer_family(slicer_path, slicer_name)
        printer_id = data.get('printer_id')
        material_type = data.get('material_type')
        if slicer_family and printer_id:
            settings_paths, filament_paths, matched_ids = _resolve_slicer_profile_paths(
                slicer_family, printer_id, material_type
            )
            applied_profile_ids = matched_ids
            if slicer_family in _SLICER_LOAD_SETTINGS_FAMILIES:
                if settings_paths:
                    cmd += ['--load-settings', ';'.join(settings_paths)]
                if filament_paths:
                    cmd += ['--load-filaments', ';'.join(filament_paths)]
            elif slicer_family in _SLICER_LOAD_INI_FAMILIES:
                for ini_path in (settings_paths + filament_paths):
                    cmd += ['--load', ini_path]

        app_logger.info(f"[Slicer] Lancement avec {len(file_paths)} fichiers...")
        open_paths = [(_prepare_model_for_slicer(fp, slicer_name, slicer_path) or fp) for fp in file_paths]
        try:
            subprocess.Popen(cmd + open_paths)
        except Exception as e:
            app_logger.info(f"[Slicer] Erreur ouverture multiple: {e}")
            subprocess.Popen(cmd + [open_paths[0]])

        try:
            conn = get_db()
            try:
                slicer_label = os.path.basename(slicer_path).replace('.exe', '')
                profile_id_to_log = applied_profile_ids[0] if applied_profile_ids else ''
                for fp in file_paths:
                    norm = fp.replace('\\', '/')
                    material_cost, elec_cost, total_cost, _w = _compute_estimated_cost(norm)
                    estimated_seconds_logged = _get_cached_slice_estimate_seconds(norm)
                    fil = _filament_info_for_file(conn, session['user_id'], norm)
                    conn.execute(
                        "INSERT INTO print_history (user_id, file_path, file_name, file_size, file_ext, slicer, source_platform, slicer_profile_id, material_cost, elec_cost, total_cost, printer_id, estimated_seconds, filament_material, filament_label, spool_source_type, spool_source_id, assignment_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (session['user_id'], norm, os.path.basename(fp),
                         os.path.getsize(fp) if os.path.exists(fp) else 0,
                         os.path.splitext(fp)[1].lower(), slicer_label,
                         detect_platform_from_path(norm), profile_id_to_log, material_cost, elec_cost, total_cost,
                         printer_id, estimated_seconds_logged, fil['material'], fil['label'],
                         fil['source_type'], fil['source_id'], fil['snapshot'])
                    )
                conn.commit()
            finally:
                conn.close()
        except Exception as log_err:
            app_logger.warning(f"[PrintHistory] Log batch échoué: {log_err}")

        return jsonify({
            "message": f"{len(file_paths)} fichiers ouverts dans le slicer",
            "count": len(file_paths),
            "stock_warnings": [] if data.get('ignore_stock') else _check_restock_for_files(file_paths, session['user_id'])
        }), 200

    except Exception as e:
        app_logger.info(f"[ERROR] api_slicer_send_batch: {e}")
        app_logger.error(f"[API] Erreur non gérée: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


