PRINTABLES_HEADERS = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
    ),
    "Content-Type": "application/json",
    "Accept": "application/json",
}

def printables_get_model_files(model_id):
    query = """
    query ModelFiles($id: ID!) {
        model: print(id: $id) {
            id
            stls { id name fileSize __typename }
            otherFiles { id name fileSize __typename }
            __typename
        }
    }
    """
    payload = {"operationName": "ModelFiles", "query": query, "variables": {"id": str(model_id)}}

    try:
        res = requests.post(PRINTABLES_API_URL, headers=PRINTABLES_HEADERS, json=payload, timeout=15)
        res.raise_for_status()
        data = res.json()
        model = (data.get('data') or {}).get('model')
        if not model:
            return []

        files = []
        for f in (model.get('stls') or []):
            if f.get('id') and f.get('name'):
                files.append({"id": f['id'], "name": f['name'], "file_type": "stl"})

        valid_other_ext = ('.3mf', '.step', '.stp', '.obj', '.amf', '.ply', '.zip')
        for f in (model.get('otherFiles') or []):
            name = f.get('name') or ''
            if f.get('id') and name.lower().endswith(valid_other_ext):
                files.append({"id": f['id'], "name": name, "file_type": "other"})

        return files

    except Exception as e:
        app_logger.warning(f"[Printables] Erreur récupération liste de fichiers (model {model_id}): {e}")
        return []

def printables_get_download_link(file_id, model_id, file_type):
    query = """
    mutation GetDownloadLink($id: ID!, $modelId: ID!, $fileType: DownloadFileTypeEnum!, $source: DownloadSourceEnum!) {
        getDownloadLink(id: $id, printId: $modelId, fileType: $fileType, source: $source) {
            ok
            errors { field messages __typename }
            output { link count ttl __typename }
            __typename
        }
    }
    """
    variables = {"id": str(file_id), "modelId": str(model_id), "fileType": file_type, "source": "model_detail"}
    payload = {"operationName": "GetDownloadLink", "query": query, "variables": variables}

    try:
        res = requests.post(PRINTABLES_API_URL, headers=PRINTABLES_HEADERS, json=payload, timeout=15)
        res.raise_for_status()
        data = res.json()
        result = (data.get('data') or {}).get('getDownloadLink')

        if result and result.get('ok') and result.get('output', {}).get('link'):
            return result['output']['link']

        if result and result.get('errors'):
            app_logger.warning(f"[Printables] GetDownloadLink erreur (file {file_id}): {result['errors']}")

    except Exception as e:
        app_logger.warning(f"[Printables] Erreur récupération lien (file {file_id}): {e}")

    return None


NEXPRINT_BASE = "https://www.nexprint.com"
NEXPRINT_API = NEXPRINT_BASE + "/gateway/api/v1/model-library-server"
NEXPRINT_DETAIL_URL = NEXPRINT_API + "/model-base-info/get"
NEXPRINT_PRESIGN_URL = NEXPRINT_API + "/common/presigned-download-url"
NEXPRINT_MODEL_CONFIG_FILE = "5"
NEXPRINT_HEADERS = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0 Safari/537.36"
    ),
    "Accept": "application/json, text/plain, */*",
    "Accept-Language": "en-US,en;q=0.9",
    "Referer": NEXPRINT_BASE + "/",
    "Origin": NEXPRINT_BASE,
}


class NexprintError(Exception):
    def __init__(self, message, status=502):
        super().__init__(message)
        self.status = status


def _nexprint_clean_token(raw):
    """Accepte la valeur brute du cookie auth_token ou un en-tête Cookie complet."""
    raw = (raw or '').strip()
    if raw.lower().startswith('cookie:'):
        raw = raw.split(':', 1)[1].strip()
    m = re.search(r'(?:^|[;\s])auth_token=([^;\s]+)', raw)
    token = m.group(1) if m else raw
    return token.strip().strip('"\'')


def _nexprint_json(resp, what):
    if resp.status_code in (401, 403):
        app_logger.warning(f"[Nexprint] {what}: HTTP {resp.status_code}")
        raise NexprintError(f"Session Nexprint refusée (HTTP {resp.status_code}) : reconnecte-toi sur nexprint.com puis recopie le cookie auth_token dans Paramètres → Comptes externes → Nexprint.", 401)
    resp.raise_for_status()
    payload = resp.json()
    if not isinstance(payload, dict):
        raise NexprintError(f"Réponse Nexprint invalide ({what}).")
    code = payload.get('code')
    msg = str(payload.get('msg') or payload.get('message') or '')
    try:
        code = int(code) if code is not None else None
    except (TypeError, ValueError):
        code = None
    if code not in (None, 0, 200):
        app_logger.warning(f"[Nexprint] {what}: code={code} msg={msg!r}")
    if code in (401, 403):
        raise NexprintError(f"Session Nexprint refusée par l'API (code {code}{' : ' + msg if msg else ''}). Recopie le cookie auth_token en entier, juste après t'être connecté sur nexprint.com.", 401)
    if code not in (None, 0, 200):
        raise NexprintError(f"Nexprint : {what} a échoué (code {code}{' : ' + msg if msg else ''}).")
    data = payload.get('data')
    return data if isinstance(data, dict) else {}


def _nexprint_auth_strategies(token):
    """Variantes d'authentification, la première reproduit celle du site officiel."""
    site = {
        "Authorization": "Bearer " + token,
        "client-id": "Nexprint",
        "user-lang": "en",
    }
    return [("site (Bearer + client-id)", site), ("cookie", {})]


def nexprint_get_model_files(model_id, auth_token, profile_hint=None):
    """Liste les fichiers 3D d'un modèle Nexprint avec une URL signée par fichier.

    Utilise l'API de Nexprint avec la session de l'utilisateur (cookie auth_token,
    puis variantes d'en-têtes si l'API répond « non connecté »).
    profile_hint : valeur de ?printConfigId= de l'URL pour ne télécharger qu'un profil.
    Retourne une liste de {'name', 'url', 'size'}. Lève NexprintError.
    """
    token = _nexprint_clean_token(auth_token)
    if not token:
        raise NexprintError("Compte Nexprint non configuré.", 400)

    app_logger.info(
        f"[Nexprint] jeton: longueur={len(token)}, points={token.count('.')}, "
        f"pourcent={'%' in token}, espaces={any(ch.isspace() for ch in token)}"
    )
    sess = requests.Session()
    sess.headers.update(NEXPRINT_HEADERS)
    sess.cookies.set('auth_token', token, domain='.nexprint.com', path='/')
    try:
        detail, last_auth_err = None, None
        for label, extra in _nexprint_auth_strategies(token):
            for k in list(sess.headers):
                if k not in NEXPRINT_HEADERS:
                    del sess.headers[k]
            sess.headers.update(extra)
            try:
                r = sess.get(NEXPRINT_DETAIL_URL, params={"id": model_id}, timeout=30)
                app_logger.info(f"[Nexprint] detail {model_id} [{label}] status={r.status_code}")
                detail = _nexprint_json(r, "lecture du modèle")
                app_logger.info(f"[Nexprint] authentification acceptée via: {label}")
                break
            except NexprintError as e:
                if e.status == 401:
                    last_auth_err = e
                    continue
                raise
            except Exception as e:
                raise NexprintError(f"Impossible de lire le modèle Nexprint : {e}")
        if detail is None:
            raise last_auth_err or NexprintError("Session Nexprint refusée.", 401)

        # Entrées à télécharger : (nom, fileId, bizId, taille, url_directe)
        profiles = [p for p in (detail.get('settingInfoList') or []) if isinstance(p, dict)]
        if profiles:
            app_logger.info(
                f"[Nexprint] {len(profiles)} profil(s); champs: {sorted(profiles[0].keys())}; "
                f"ids: {[p.get('id') for p in profiles]}"
            )
        if profile_hint:
            hint = str(profile_hint)
            want = re.sub(r'\D', '', hint)

            def _matches(p):
                for v in p.values():
                    if isinstance(v, (str, int)) and not isinstance(v, bool) and str(v) == hint:
                        return True
                return bool(want) and re.sub(r'\D', '', str(p.get('id') or '')) == want

            picked = [p for p in profiles if _matches(p)]
            if picked:
                profiles = picked
            else:
                app_logger.info(f"[Nexprint] profil {profile_hint} introuvable, tous les profils seront téléchargés")

        entries, seen = [], set()
        for prof in profiles:
            finfo = prof.get('settingFile')
            if not isinstance(finfo, dict) or not finfo.get('fileId'):
                continue
            fid = str(finfo['fileId'])
            if fid in seen:
                continue
            seen.add(fid)
            name = finfo.get('fileName') or ''
            stem = os.path.splitext(name)[0]
            if not name or stem.isdigit():
                name = f"{prof.get('settingName') or model_id}"
            if os.path.splitext(name)[1].lower() != '.3mf':
                name += '.3mf'
            entries.append((name, fid, str(prof.get('id') or ''), finfo.get('fileSize'), None))

        if not entries:
            for key in ('modelFileInfoList', 'files', 'modelFileList'):
                for f in detail.get(key) or []:
                    if not isinstance(f, dict):
                        continue
                    direct = f.get('fileUrl') or f.get('url') or f.get('downloadUrl')
                    fname = f.get('fileName') or f.get('name') or ''
                    if direct and fname:
                        entries.append((fname, '', '', f.get('fileSize'), direct))
                if entries:
                    break

        strategies = _nexprint_auth_strategies(token)
        working = [0]

        def _apply(idx):
            for k in list(sess.headers):
                if k not in NEXPRINT_HEADERS:
                    del sess.headers[k]
            sess.headers.update(strategies[idx][1])

        def _presign(fid, biz):
            """Crée le lien signé ; essaie les variantes d'authentification si « non connecté »."""
            last = None
            order = [working[0]] + [i for i in range(len(strategies)) if i != working[0]]
            for idx in order:
                _apply(idx)
                try:
                    pr = sess.post(NEXPRINT_PRESIGN_URL, json={"fileInfoList": [
                        {"fileId": fid, "type": NEXPRINT_MODEL_CONFIG_FILE, "bizId": biz}
                    ]}, timeout=30)
                    pdata = _nexprint_json(pr, "création du lien signé")
                    working[0] = idx
                    app_logger.info(f"[Nexprint] lien signé obtenu via: {strategies[idx][0]}")
                    return pdata
                except NexprintError as e:
                    if e.status == 401:
                        last = e
                        continue
                    raise
            raise last or NexprintError("Session Nexprint refusée.", 401)

        files = []
        for name, fid, biz, size, direct in entries:
            url = direct
            if not url:
                try:
                    pdata = _presign(fid, biz)
                    lst = pdata.get('fileInfoList')
                    if isinstance(lst, list) and lst and isinstance(lst[0], dict):
                        url = (lst[0].get('resultUrl') or lst[0].get('downloadUrl')
                               or lst[0].get('fileUrl') or lst[0].get('url'))
                except NexprintError:
                    raise
                except Exception as e:
                    app_logger.warning(f"[Nexprint] Lien signé impossible pour {name}: {e}")
            if url and url.lower().startswith('http'):
                files.append({"name": name, "url": url, "size": size})
        app_logger.info(f"[Nexprint] {len(files)} fichier(s) prêt(s) pour {model_id}")
        return files
    finally:
        sess.close()


MAKERWORLD_API = "https://api.bambulab.com"
MAKERWORLD_DL_HEADERS = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
    ),
    "Accept": "application/json",
}

def makerworld_get_model_files(model_id, bearer_token=None, profile_id=None, preferred_format=None, diag=None):
    if diag is None:
        diag = {}
    headers = {
        "User-Agent": "BambuStudio/01.09.00.00",
        "Accept": "application/json",
        "Referer": f"https://makerworld.com/en/models/{model_id}",
        # en-têtes envoyés par Bambu Studio : sans eux, l'API peut répondre 200 mais sans lien de téléchargement
        "X-BBL-Client-Type": "slicer",
        "X-BBL-Client-Name": "BambuStudio",
        "X-BBL-Client-Version": "01.09.00.00",
        "X-BBL-OS-Type": "windows",
        "X-BBL-Language": "en-US",
    }
    if bearer_token:
        headers["Authorization"] = f"Bearer {bearer_token}"

    files = []
    try:
        r = requests.get(
            f"{MAKERWORLD_API}/v1/design-service/design/{model_id}",
            headers=headers,
            timeout=20
        )
        app_logger.info(f"[MakerWorld] design/{model_id} status={r.status_code}")
        if r.status_code in (401, 403) and bearer_token:
            # Jeton périmé : la fiche d'un modèle public reste lisible sans session, on retente sans jeton
            diag['auth_rejected'] = r.status_code
            app_logger.warning(f"[MakerWorld] design/{model_id} refusé avec le jeton ({r.status_code}), nouvel essai sans jeton")
            _h_anon = {k: v for k, v in headers.items() if k != "Authorization"}
            r = requests.get(f"{MAKERWORLD_API}/v1/design-service/design/{model_id}", headers=_h_anon, timeout=20)
            app_logger.info(f"[MakerWorld] design/{model_id} (sans jeton) status={r.status_code}")
        if not r.ok:
            diag['design_status'] = r.status_code
            app_logger.warning(f"[MakerWorld] design/{model_id} non-OK: {r.status_code} {r.text[:200]}")
            return files

        data = r.json()
        alpha_model_id = data.get("modelId") or data.get("model_id") or ""
        app_logger.info(f"[MakerWorld] alphaModelId={alpha_model_id}")

        design_title = (
            data.get("title") or
            data.get("titleTranslated") or
            data.get("slug") or
            f"makerworld_{model_id}"
        ).strip()
        design_title = re.sub(r'[<>:"/\\|?*]', '_', design_title)
        app_logger.info(f"[MakerWorld] Titre du design: '{design_title}'")

        instances = (
            data.get("instances") or
            data.get("designProfileList") or
            data.get("profileList") or
            data.get("profiles") or
            []
        )
        app_logger.info(f"[MakerWorld] {len(instances)} instance(s) disponible(s)")
        if instances:
            app_logger.info(f"[MakerWorld] instance[0] keys: {list(instances[0].keys())}")
            app_logger.info(f"[MakerWorld] instance[0] sample: { {k: instances[0][k] for k in list(instances[0].keys())[:8]} }")

        target_instances = instances
        if profile_id and instances:
            matched = [inst for inst in instances if str(inst.get('id', '')) == str(profile_id)]
            if matched:
                target_instances = matched
                app_logger.info(f"[MakerWorld] Instance ciblée: id={profile_id} → profileId={matched[0].get('profileId')}")
            else:
                app_logger.warning(f"[MakerWorld] id={profile_id} non trouvé dans les instances, téléchargement de toutes les instances")

        for inst in target_instances:
            pid_primary = inst.get("profileId")
            pid_fallback = inst.get("id")
            if not pid_primary and not pid_fallback:
                continue

            pname = design_title
            if len(target_instances) > 1:
                inst_idx = target_instances.index(inst) + 1
                pname = f"{design_title}_{inst_idx}"

            app_logger.info(f"[MakerWorld] Instance id={pid_fallback} profileId={pid_primary} → '{pname}'")

            try:
                params = {}
                if alpha_model_id:
                    params["model_id"] = alpha_model_id

                r_dl = requests.get(
                    f"{MAKERWORLD_API}/v1/iot-service/api/user/profile/{pid_primary}",
                    params=params,
                    headers=headers,
                    timeout=15
                )
                app_logger.info(f"[MakerWorld] iot-service/profile/{pid_primary} status={r_dl.status_code}")
                if r_dl.status_code in (401, 403):
                    diag['auth_rejected'] = r_dl.status_code
                elif not r_dl.ok:
                    diag['profile_status'] = r_dl.status_code

                if not r_dl.ok and pid_fallback and pid_fallback != pid_primary:
                    app_logger.info(f"[MakerWorld] Retry avec id={pid_fallback}")
                    r_dl = requests.get(
                        f"{MAKERWORLD_API}/v1/iot-service/api/user/profile/{pid_fallback}",
                        params=params,
                        headers=headers,
                        timeout=15
                    )
                    app_logger.info(f"[MakerWorld] iot-service/profile/{pid_fallback} status={r_dl.status_code}")

                if r_dl.ok:
                    dl_data = r_dl.json()
                    app_logger.info(f"[MakerWorld] profile keys={list(dl_data.keys())}")

                    dl_url = (
                        dl_data.get("url") or
                        dl_data.get("downloadUrl") or
                        dl_data.get("download_url") or
                        dl_data.get("fileUrl")
                    )
                    if not dl_url:
                        _dd = dl_data if isinstance(dl_data, dict) else {}
                        _pmsg = str(_dd.get('message') or _dd.get('error') or '')[:160]
                        app_logger.warning(f"[MakerWorld] iot-service sans lien : code={_dd.get('code')!r} message={_pmsg!r} status={_dd.get('status')!r} filename={_dd.get('filename')!r} url_vide={_dd.get('url')!r}")
                        diag['profile_msg'] = (f"code {_dd.get('code')} : {_pmsg}" if (_dd.get('code') or _pmsg) else "réponse sans lien")
                        # repli : point d'accès « instance » utilisé par le site MakerWorld (renvoie {name, url})
                        for _inst_id in [x for x in dict.fromkeys([pid_fallback, pid_primary]) if x]:
                            try:
                                r_f = requests.get(f"{MAKERWORLD_API}/v1/design-service/instance/{_inst_id}/f3mf",
                                                   params={"type": "download"}, headers=headers, timeout=15)
                                app_logger.info(f"[MakerWorld] instance/{_inst_id}/f3mf status={r_f.status_code}")
                                if r_f.ok:
                                    _jf = r_f.json()
                                    app_logger.info(f"[MakerWorld] f3mf keys={list(_jf.keys()) if isinstance(_jf, dict) else type(_jf).__name__}")
                                    dl_url = (_jf.get("url") or _jf.get("downloadUrl")) if isinstance(_jf, dict) else None
                                    if dl_url:
                                        diag.pop('profile_msg', None)
                                        break
                                else:
                                    app_logger.warning(f"[MakerWorld] f3mf refusé : {r_f.status_code} {r_f.text[:160]}")
                            except Exception as _ef:
                                app_logger.warning(f"[MakerWorld] f3mf erreur : {_ef}")
                    if dl_url:
                        ext = os.path.splitext(dl_url.split("?")[0])[1].lower()
                        if not ext:
                            ext = ".3mf"
                        safe_name = re.sub(r'[<>:"/\\|?*]', '_', pname) + ext
                        files.append({"name": safe_name, "url": dl_url, "format": ext.lstrip('.')})
                        app_logger.info(f"[MakerWorld] ✅ {safe_name}")

                        if profile_id and target_instances != instances:
                            break
                else:
                    app_logger.warning(f"[MakerWorld] Deux essais échoués pour instance id={pid_fallback} profileId={pid_primary}: {r_dl.status_code} {r_dl.text[:200]}")

            except Exception as ep:
                app_logger.warning(f"[MakerWorld] Erreur iot-service/profile/{pid_fallback}: {ep}")

        if not files or (preferred_format == 'stl' and not any(f['format'] == 'stl' for f in files)):
            app_logger.info(f"[MakerWorld] Tentative endpoint STL direct...")
            try:
                r_stl = requests.get(
                    f"{MAKERWORLD_API}/v1/design-service/design/{model_id}/stl",
                    params={"profile_id": profile_id} if profile_id else {},
                    headers=headers,
                    timeout=20
                )
                app_logger.info(f"[MakerWorld] design/{model_id}/stl status={r_stl.status_code}")

                if r_stl.ok:
                    stl_data = r_stl.json()
                    app_logger.info(f"[MakerWorld] /stl keys={list(stl_data.keys())}")

                    stl_url = stl_data.get("url") or stl_data.get("downloadUrl") or stl_data.get("download_url")
                    if stl_url:
                        files.append({"name": f"makerworld_{model_id}.zip", "url": stl_url, "format": "zip"})
                        app_logger.info(f"[MakerWorld] ✅ STL ZIP via design/{model_id}/stl")

            except Exception as e_stl:
                app_logger.warning(f"[MakerWorld] Endpoint STL échoué: {e_stl}")

    except Exception as e:
        app_logger.warning(f"[MakerWorld] Erreur design/{model_id}: {e}")

    app_logger.info(f"[MakerWorld] Modèle {model_id}: {len(files)} fichier(s) trouvé(s)")

    if preferred_format and files:
        target_ext = preferred_format
        filtered = [f for f in files if f.get('format', '') == target_ext]
        if filtered:
            app_logger.info(f"[MakerWorld] Filtre format '{preferred_format}': {len(filtered)} fichier(s) gardé(s)")
            files = filtered
        else:
            app_logger.warning(f"[MakerWorld] Format '{preferred_format}' non disponible, retour de tous les fichiers ({len(files)})")

    return files

def _makerworld_save_token(user_id, email, token):
    conn = get_db()
    try:
        token_enc = encrypt_password(token) if token else None
        conn.execute("""
            INSERT INTO account_credentials (user_id, platform, email, api_key, last_login)
            VALUES (?, 'makerworld', ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(user_id, platform) DO UPDATE SET
                email = excluded.email,
                api_key = excluded.api_key,
                last_login = CURRENT_TIMESTAMP
        """, (user_id, email, token_enc))
        conn.commit()
    finally:
        conn.close()
    app_logger.info(f"[MakerWorld] Token sauvegardé pour user {user_id} ({email})")

@app.route('/api/accounts/makerworld/login', methods=['POST'])
@login_required
def makerworld_login_step1():
    data = request.json or {}
    email    = (data.get('email') or '').strip()
    password = (data.get('password') or '').strip()

    if not email or not password:
        return jsonify({"error": "Email et mot de passe requis"}), 400

    try:
        r = requests.post(
            f"{MAKERWORLD_API}/v1/user-service/user/login",
            json={"account": email, "password": password},
            headers={"Content-Type": "application/json", "User-Agent": "BambuStudio/01.09.00.00"},
            timeout=15
        )
        body = r.json()
    except Exception as e:
        return jsonify({"error": f"Erreur réseau : {e}"}), 502

    login_type = body.get("loginType", "")
    if login_type == "verifyCode":
        return jsonify({"needCode": True}), 200

    access_token = body.get("accessToken") or body.get("token")
    if access_token:
        _makerworld_save_token(session['user_id'], email, access_token)
        return jsonify({"success": True}), 200

    msg = body.get("message") or body.get("error") or "Identifiants incorrects"
    return jsonify({"error": msg}), 401

@app.route('/api/accounts/makerworld/verify', methods=['POST'])
@login_required
def makerworld_login_step2():
    data = request.json or {}
    email = (data.get('email') or '').strip()
    code  = (data.get('code') or '').strip()

    if not email or not code:
        return jsonify({"error": "Email et code requis"}), 400

    try:
        r = requests.post(
            f"{MAKERWORLD_API}/v1/user-service/user/login",
            json={"account": email, "code": code},
            headers={"Content-Type": "application/json", "User-Agent": "BambuStudio/01.09.00.00"},
            timeout=15
        )
        body = r.json()
    except Exception as e:
        return jsonify({"error": f"Erreur réseau : {e}"}), 502

    access_token = body.get("accessToken") or body.get("token")
    if access_token:
        _makerworld_save_token(session['user_id'], email, access_token)
        return jsonify({"success": True}), 200

    msg = body.get("message") or body.get("error") or "Code invalide ou expiré"
    return jsonify({"error": msg}), 401

@app.route('/api/accounts/makerworld/disconnect', methods=['DELETE'])
@login_required
def makerworld_disconnect():
    conn = get_db()
