            if not nx_files:
                active_downloads.pop(download_id, None)
                return jsonify({
                    "error": "Aucun fichier 3D téléchargeable trouvé pour ce modèle Nexprint."
                }), 404

            nx_dl_headers = dict(DL_HEADERS)
            total_files = len(nx_files)
            results = []
