@app.route('/api/print-queue', methods=['POST'])
@login_required
def api_add_to_print_queue():
    try:
        data = request.json or {}
        file_path = data.get('path')
        note = (data.get('note') or '').strip() or None
        if not file_path:
            return jsonify({"error": "Chemin requis"}), 400

        conn = get_db()
        try:
            existing = conn.execute(
                "SELECT id FROM print_queue WHERE user_id = ? AND file_path = ?",
                (session['user_id'], file_path)
            ).fetchone()
            if existing:
                return jsonify({"message": "Déjà dans la file d'attente", "already_queued": True}), 200
            max_pos = conn.execute(
                "SELECT COALESCE(MAX(position), -1) as m FROM print_queue WHERE user_id = ?",
                (session['user_id'],)
            ).fetchone()['m']
            conn.execute(
                "INSERT INTO print_queue (user_id, file_path, position, note) VALUES (?, ?, ?, ?)",
                (session['user_id'], file_path, max_pos + 1, note)
            )
            conn.commit()
        finally:
            conn.close()
        return jsonify({"message": "Ajouté à la file d'attente", "queued": True}), 200
    except Exception as e:
        app_logger.error(f"[API] Erreur api_add_to_print_queue: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


