@app.route('/api/presence/heartbeat', methods=['POST'])
@login_required
def api_presence_heartbeat():
    try:
        data = request.json or {}
        client_id = (data.get('client_id') or '').strip()
        if not client_id:
            return jsonify({"error": "client_id requis"}), 400
        with _active_sessions_lock:
            _active_sessions[client_id] = {
                "user_id": session['user_id'],
                "page": data.get('page') or '',
                "file_path": data.get('file_path') or None,
                "file_name": data.get('file_name') or None,
                "last_seen": time.time(),
            }
            now = time.time()
            expired = [cid for cid, s in _active_sessions.items() if now - s["last_seen"] > PRESENCE_TIMEOUT_SECONDS]
            for cid in expired:
                _active_sessions.pop(cid, None)
        return jsonify({"message": "ok"}), 200
    except Exception as e:
        app_logger.error(f"[API] Erreur api_presence_heartbeat: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500


