        now = time.time()
        with _active_sessions_lock:
            others = [
                {"page": s["page"], "file_path": s["file_path"], "file_name": s["file_name"],
                 "seconds_ago": int(now - s["last_seen"])}
                for cid, s in _active_sessions.items()
                if cid != client_id and s["user_id"] == session['user_id'] and now - s["last_seen"] <= PRESENCE_TIMEOUT_SECONDS
            ]
