def _project_effective_status(stored, total_needed, total_printed):
    """Un projet dont toutes les pièces sont imprimées est « terminé », même si le statut enregistré
    est resté « in_progress » (le statut n'est jamais mis à jour à la main dans l'interface)."""
    if stored == 'done':
        return 'done'
    if total_needed > 0 and total_printed >= total_needed:
        return 'done'
    return stored or 'in_progress'


@app.route('/api/projects', methods=['GET'])
@login_required
def api_get_projects():
    try:
        conn = get_db()
        try:
            projects = conn.execute(
                "SELECT * FROM projects WHERE user_id = ? ORDER BY updated_at DESC",
                (session['user_id'],)
            ).fetchall()

            result = []
            for p in projects:
                pf = conn.execute(
                    "SELECT file_path, quantity_needed, quantity_printed FROM project_files WHERE project_id = ? ORDER BY position, added_at",
                    (p['id'],)
                ).fetchall()
                files = [dict(f) for f in pf]
                total_needed = sum(f['quantity_needed'] for f in files)
                total_printed = sum(min(f['quantity_printed'], f['quantity_needed']) for f in files)
                result.append({
                    "id": p['id'],
                    "name": p['name'],
                    "description": p['description'],
                    "color": p['color'],
                    "status": _project_effective_status(p['status'], total_needed, total_printed),
                    "created_at": p['created_at'],
                    "updated_at": p['updated_at'],
                    "file_count": len(files),
                    "total_needed": total_needed,
                    "total_printed": total_printed,
                    "progress": round((total_printed / total_needed) * 100) if total_needed > 0 else 0,
                    "files": [f['file_path'] for f in files[:4]]
                })
        finally:
            conn.close()
        return jsonify(result)
    except Exception as e:
        app_logger.info(f"[ERROR] api_get_projects: {e}")
        app_logger.error(f"[API] Erreur non gérée: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500

