def _extract_bed_config(cfg):
    """Extrait bed_x/bed_y/bed_z (mm) de la config reçue ; ignore les valeurs absentes ou invalides."""
    out = {}
    if not isinstance(cfg, dict):
        return out
    for k in ('bed_x', 'bed_y', 'bed_z'):
        try:
            v = float(cfg.get(k))
        except (TypeError, ValueError):
            continue
        if 0 < v < 10000:
            out[k] = int(v) if v == int(v) else v
    if cfg.get('timelapse'):
        out['timelapse'] = True
    return out


@app.route('/api/printers', methods=['POST'])
@login_required
def api_add_printer():
    data = request.json
    name = data.get('name')
    ptype = data.get('type')
    ip = data.get('ip')
    api_key = data.get('api_key', '')
    raw_config = data.get('config', {})

    if ptype == 'bambu':
        code = raw_config.get('code', '')
        serial = raw_config.get('serial', '')
        api_key = code
        raw_config = {'code': code, 'serial': serial, 'model': str(raw_config.get('model') or 'A1').upper()[:20]}
    elif ptype == 'bambuddy':
        raw_config = _bambuddy_clean_config(raw_config)
    elif ptype == 'elegoo_cc2':
        code = raw_config.get('code', '') or '123456'
        api_key = code
        raw_config = {'code': code}
    elif ptype == 'flashforge':
        code = raw_config.get('code', '')
        serial = raw_config.get('serial', '')
        api_key = code
        raw_config = {'code': code, 'serial': serial}

    raw_config.update(_extract_bed_config(data.get('config')))
    _ext = _clean_external_url((data.get('config') or {}).get('external_url'))
    raw_config.pop('external_url', None)
    if ptype in HTTP_PRINTER_TYPES:
        if _ext:
            raw_config['external_url'] = _ext
            _printer_ext_urls[ip] = _ext
    config = json.dumps(raw_config)

    if not name or not ip or not ptype:
        return jsonify({"error": "Champs requis"}), 400

    conn = get_db()
    try:
        is_connected = printer_hub.connect_printer({
            'id': 0, 'type': ptype, 'ip': ip, 'api_key': api_key,
            'config': json.loads(config) if config else {}
        })

        conn.execute("""
            INSERT INTO printers (user_id, name, type, ip, api_key, config, is_connected)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        """, (session['user_id'], name, ptype, ip, encrypt_password(api_key) if api_key else None, config, is_connected))
        conn.commit()
        _printers_ext_reload()

        return jsonify({"message": "Imprimante ajoutée", "connected": is_connected}), 200

    except Exception as e:
        app_logger.error(f"[API] Erreur non gérée: {e}")
        return jsonify({"error": "Une erreur interne est survenue lors du traitement de la requête"}), 500
    finally:
        conn.close()

@app.route('/api/printers/discover', methods=['GET'])
@login_required
def api_discover_printers():
    conn = get_db()
    try:
        existing_ips = {row['ip'] for row in conn.execute(
            "SELECT ip FROM printers WHERE user_id = ?", (session['user_id'],)
        ).fetchall()}
    finally:
        conn.close()

    results = []
    results_lock = threading.Lock()

    def _run(fn):
        try:
            r = fn()
            with results_lock:
                results.extend(r)
        except Exception as e:
            app_logger.info(f"[Discover] Erreur méthode de découverte: {e}")

    threads = [
        threading.Thread(target=_run, args=(_discover_bambu_ssdp,), daemon=True),
        threading.Thread(target=_run, args=(_discover_elegoo_broadcast,), daemon=True),
        threading.Thread(target=_run, args=(_discover_flashforge,), daemon=True),
        threading.Thread(target=_run, args=(_scan_lan_for_printers,), daemon=True),
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=15)

    seen_ips, filtered = set(), []
    for r in results:
        if not r.get('ip') or r['ip'] in existing_ips or r['ip'] in seen_ips:
            continue
        seen_ips.add(r['ip'])
        filtered.append(r)

    return jsonify({"printers": filtered}), 200


# --- Miniature du fichier en cours pour les impressions lancées hors Stellio (Klipper / Moonraker) ---
def _klipper_fetch_job_thumbnail(base, filename):
    """Miniature intégrée au G-code (slicer) via Moonraker : (octets, type MIME) ou None."""
    from urllib.parse import quote
    meta = requests.get(f"{base}/server/files/metadata", params={'filename': filename}, timeout=5).json()
    thumbs = [t for t in ((meta.get('result') or {}).get('thumbnails') or []) if t.get('relative_path')]
    if not thumbs:
        return None
    # plus grande miniature de 400 px de large maximum, sinon la plus petite disponible
    small = [t for t in thumbs if (t.get('width') or 0) <= 400]
    best = max(small, key=lambda t: (t.get('width') or 0) * (t.get('height') or 0)) if small \
        else min(thumbs, key=lambda t: (t.get('width') or 0) * (t.get('height') or 0))
    folder = os.path.dirname(filename.replace('\\', '/'))
    rel = best['relative_path']
    path = f"{folder}/{rel}" if folder else rel
    img = requests.get(f"{base}/server/files/gcodes/{quote(path)}", timeout=8)
    img.raise_for_status()
    return img.content, img.headers.get('Content-Type', 'image/png')


@app.route('/api/printers/<int:pid>/job-thumb', methods=['GET'])
@login_required
def api_printer_job_thumb(pid):
    conn = get_db()
    p = conn.execute("SELECT * FROM printers WHERE id = ? AND user_id = ?", (pid, session['user_id'])).fetchone()
    conn.close()
    if not p:
        return jsonify({"error": "Not found"}), 404
    printer = parse_printer_config(p)
    if printer.get('type') != 'klipper':
        return jsonify({"error": "Miniature non disponible pour ce type d'imprimante"}), 404
    filename = (request.args.get('file') or '').strip()
    if not filename or '..' in filename.replace('\\', '/').split('/'):
        return jsonify({"error": "Fichier invalide"}), 400
    cfg = printer.get('config') if isinstance(printer.get('config'), dict) else {}
    base = _pbase(printer['ip'], cfg.get('port', '7125'))
    try:
        result = _klipper_fetch_job_thumbnail(base, filename)
    except Exception as e:
        app_logger.info(f"[Printer] Miniature du job indisponible ({filename}): {e}")
        result = None
    if not result:
        return jsonify({"error": "Miniature non trouvée"}), 404
    resp = Response(result[0], mimetype=result[1])
    resp.headers['Cache-Control'] = 'private, max-age=300'
    return resp


@app.route('/api/printers/<int:pid>/status', methods=['GET'])
@login_required
def api_printer_status(pid):
    conn = get_db()
    p = conn.execute(
        "SELECT * FROM printers WHERE id = ? AND user_id = ?",
        (pid, session['user_id'])
    ).fetchone()
    conn.close()

    if not p:
        return jsonify({"error": "Not found"}), 404

    printer = parse_printer_config(p)
    status = printer_hub.get_status(printer)

    conn = get_db()
    is_online = status.get('status') not in ['error', 'offline', 'timeout']

    now = datetime.datetime.now()
    last_poll_raw = p['last_status_poll_at'] if 'last_status_poll_at' in p.keys() else None
    if status.get('status') == 'printing' and last_poll_raw and p['type'] != 'klipper':
        try:
            last_poll = datetime.datetime.fromisoformat(last_poll_raw)
            delta_hours = (now - last_poll).total_seconds() / 3600
            if 0 < delta_hours < (10 / 60):
                conn.execute("UPDATE printers SET total_print_hours = total_print_hours + ? WHERE id = ?",
                             (delta_hours, pid))
        except Exception:
            pass

    for attempt in range(3):
        try:
            conn.execute("UPDATE printers SET is_connected = ?, last_status_poll_at = ? WHERE id = ?",
                         (is_online, now.isoformat(timespec='seconds'), pid))
            conn.commit()
            break
        except sqlite3.OperationalError as e:
            if 'locked' in str(e).lower() and attempt < 2:
                time.sleep(0.3 * (attempt + 1))
                continue
            app_logger.warning(f"[PrinterStatus] Écriture ignorée (verrou DB persistant) pour l'imprimante {pid}: {e}")
            break
    conn.close()

    last_print = status.get('last_print') or {}
    if last_print.get('filename') and last_print.get('duration'):
        try:
            _autofill_actual_print_time(session['user_id'], pid, last_print['filename'],
                                         last_print['duration'], last_print.get('finished_at'))
        except Exception as e:
            app_logger.info(f"[PrinterStatus] autofill temps réel ignoré: {e}")

    return jsonify(status)

