def _remote_start_kwargs(settings):
    return {
        'token': settings.get('cloudflare_tunnel_token') or None,
        'fixed_url': settings.get('cloudflare_fixed_url') or None,
        'custom_url': settings.get('remote_access_custom_url') or None,
    }


def _normalize_custom_remote_url(raw):
    from urllib.parse import urlsplit
    url = (raw or '').strip()
    if not url:
        return None, "L'adresse est requise"
    if len(url) > 255 or any(ch.isspace() or ch in '"\'<>\\`' for ch in url):
        return None, "Adresse invalide (trop longue, espaces ou caractères interdits)"
    if '://' not in url:
        url = 'https://' + url
    try:
        parts = urlsplit(url)
        port = parts.port  
    except ValueError:
        return None, "Adresse ou port invalide"
    if parts.scheme not in ('http', 'https'):
        return None, "L'adresse doit commencer par http:// ou https://"
    host = parts.hostname or ''
    if not host or not re.fullmatch(r'[A-Za-z0-9._:\-]+', host):
        return None, "Nom de domaine ou adresse IP invalide"
    if parts.username or parts.password:
        return None, "N'indiquez pas d'identifiants dans l'adresse"
    if parts.query or parts.fragment:
        return None, "L'adresse ne doit contenir ni paramètres (?) ni ancre (#)"
    return f"{parts.scheme}://{parts.netloc}{parts.path.rstrip('/')}", None


@app.route('/api/remote-access/custom', methods=['POST'])
@login_required
def api_remote_access_custom():
    data = request.json or {}
    url, err = _normalize_custom_remote_url(data.get('url'))
    if err:
        return jsonify({"error": err}), 400

    current_settings = load_settings() or {}
    current_settings['remote_access_custom_url'] = url
    save_settings(current_settings)

    if current_settings.get('remote_access_enabled', False):
        threading.Thread(
            target=restart_remote_access,
            args=(DATA_DIR, SERVER_PORT, app_logger),
            kwargs=_remote_start_kwargs(current_settings),
            daemon=True
        ).start()
    return jsonify({"message": "Adresse personnalisée enregistrée.", "url": url}), 200


